/*
 * Authenticates to Salesforce, checks for an existing CampaignMember, creates one when absent, and returns member details or patch guidance for the delegate workflow.
 * Branch before: None unless upstream routing already selected the create or retry-create path for this delegate.
 * Branch after: Route by output state: skipped, found_needs_patch, created, lock_error, or error.
 * Expected inputs: hs_delegate_id, salesforce_campaign_id, registration_status, exactly one of salesforcecontactid or salesforceleadid, optional salesforce_campaign_membership_id, email.
 * Expected outputs: log, http, http_message, other, membership_id, m_id_known, m_id_status, operation, lock_error.
 */
const crypto = require('crypto');
const https = require('https');
const { URL } = require('url');

const THIS_ACTION = 'new_delegate_record_CCA1';
const WORKFLOW_NAME = 'Delegate New > New SFDC Campaign member';
const ACTION_VARIANT = 'post';
const DEFAULT_LOGIN_URL = 'https://login.salesforce.com';
const DEFAULT_API_VERSION = 'v62.0';
const SF_PROD_CONSUMER_KEY_SECRET = 'SF_CONSUMER_KEY_PROD';
const SF_PROD_USERNAME = 'hubspot.integration@nanoporetech.com';
const SF_PROD_JWT_PART_NAMES = ['SF_JWT_PART_01', 'SF_JWT_PART_02', 'SF_JWT_PART_03'];
const EXPOSED_OUTPUT_FIELDS = ['log', 'http', 'http_message', 'other', 'membership_id', 'm_id_known', 'm_id_status', 'operation', 'lock_error'];

function safeStr(value) {
  return String(value == null ? '' : value).trim();
}

function norm(value) {
  return safeStr(value).toLowerCase();
}

function desiredStatusFromRegistrationStatus(value) {
  const normalized = norm(value);
  if (!normalized) return 'Registered';
  if (normalized === 'confirmed') return 'Registered';
  if (normalized === 'attended') return 'Attended';
  return '';
}

function jsonCompact(obj) {
  return JSON.stringify(obj == null ? {} : obj);
}

function selectOutputFields(outputs) {
  return EXPOSED_OUTPUT_FIELDS.reduce((acc, key) => {
    acc[key] = outputs[key];
    return acc;
  }, {});
}

function friendly(value) {
  const map = {
    200: 'OK',
    201: 'Created',
    204: 'No content',
    400: 'Bad Request – Your request is wrong',
    401: 'Unauthorized (credentials)',
    403: 'Forbidden (scope)',
    404: 'Not Found',
    405: 'Method Not Allowed',
    408: 'Request timeout',
    409: 'Conflict',
    422: 'Unprocessable entity',
    429: 'Too Many Requests',
    500: 'Internal Server Error',
    502: 'Bad gateway / processing limit met',
    503: 'Service temporarily unavailable',
    504: 'Gateway timeout / processing limit met',
  };
  if (typeof value === 'number') return map[value] || `HTTP ${value}`;
  const text = String(value || '');
  if (text === 'Timed_out') return 'Timeout';
  if (text === 'Request_error') return 'Request error';
  return 'No response';
}

function deriveHttpMessage(httpDict, overrides) {
  const out = {};
  Object.entries(httpDict || {}).forEach(([key, value]) => {
    const asNum = Number(value);
    out[key] = Number.isFinite(asNum) ? friendly(asNum) : friendly(value);
  });
  Object.entries(overrides || {}).forEach(([key, value]) => {
    if (value !== undefined && value !== null && String(value).trim() !== '') out[key] = String(value);
  });
  return out;
}

function envFirst(keys) {
  const list = Array.isArray(keys) ? keys : [keys];
  for (const key of list) {
    const raw = process.env[key];
    if (raw == null) continue;
    const value = String(raw).trim();
    if (value) return value;
  }
  return '';
}

function sfdcApiVersion() {
  const raw = envFirst(['salesforce_api_version', 'SFDC_API_VERSION', 'SALESFORCE_API_VERSION']) || DEFAULT_API_VERSION;
  const value = raw.replace(/^\//, '').trim();
  if (!value) return DEFAULT_API_VERSION;
  if (/^\d/.test(value)) return `v${value}`;
  return value;
}

function base64url(input) {
  const buf = Buffer.isBuffer(input) ? input : Buffer.from(String(input), 'utf8');
  return buf.toString('base64').replace(/=/g, '').replace(/\+/g, '-').replace(/\//g, '_');
}

function buildJwt({ iss, sub, aud, expiresInSec, keyObject }) {
  const now = Math.floor(Date.now() / 1000);
  const header = { alg: 'RS256', typ: 'JWT' };
  const payload = { iss, sub, aud, iat: now, exp: now + expiresInSec };
  const signingInput = `${base64url(jsonCompact(header))}.${base64url(jsonCompact(payload))}`;
  const signature = crypto.sign('RSA-SHA256', Buffer.from(signingInput, 'utf8'), keyObject);
  return `${signingInput}.${base64url(signature)}`;
}

function validateBase64String(b64) {
  if (!b64) return { ok: false, reason: 'empty' };
  if (!/^[A-Za-z0-9+/=]+$/.test(b64)) return { ok: false, reason: 'non_base64_chars' };
  if (b64.length % 4 !== 0) return { ok: false, reason: 'length_not_multiple_of_4' };
  return { ok: true };
}

function getPrivateKeyFromSecrets(httpStatuses) {
  const parts = SF_PROD_JWT_PART_NAMES.map((name) => envFirst(name));
  if (parts.some((part) => !part)) {
    httpStatuses.sfdc_key = 'NO_RESP';
    return {
      keyObject: null,
      meta: { key_scheme: 'SF_JWT_PART_prod_3parts', key_parts_expected: SF_PROD_JWT_PART_NAMES.length, key_parts_found: parts.filter(Boolean).length },
      error: 'Missing private key parts',
    };
  }
  const scheme = 'SF_JWT_PART_prod_3parts';

  const b64 = parts.map((item) => String(item).replace(/\s+/g, '')).join('');
  const valid = validateBase64String(b64);
  if (!valid.ok) {
    httpStatuses.sfdc_key = 'INVALID';
    return {
      keyObject: null,
      meta: { key_scheme: scheme, key_parts: parts.length, key_b64_len: b64.length, key_b64_reason: valid.reason },
      error: `Invalid base64 private key (${valid.reason})`,
    };
  }

  let pem = '';
  try {
    pem = Buffer.from(b64, 'base64').toString('utf8');
  } catch (err) {
    httpStatuses.sfdc_key = 'INVALID';
    return {
      keyObject: null,
      meta: { key_scheme: scheme, key_parts: parts.length, key_b64_len: b64.length },
      error: `Key decode failed: ${safeStr(err && err.message)}`,
    };
  }

  if (!pem.startsWith('-----BEGIN')) {
    httpStatuses.sfdc_key = 'INVALID';
    return {
      keyObject: null,
      meta: { key_scheme: scheme, key_parts: parts.length, pem_prefix: pem.slice(0, 20) },
      error: 'Decoded key is not PEM',
    };
  }

  try {
    const keyObject = crypto.createPrivateKey(pem);
    const fingerprint = crypto.createHash('sha256').update(pem).digest('hex').slice(0, 12);
    return {
      keyObject,
      meta: { key_scheme: scheme, key_parts: parts.length, key_b64_len: b64.length, pem_len: pem.length, key_fp: fingerprint },
      error: null,
    };
  } catch (err) {
    httpStatuses.sfdc_key = 'INVALID';
    return {
      keyObject: null,
      meta: { key_scheme: scheme, key_parts: parts.length, pem_len: pem.length },
      error: `PEM parse failed: ${safeStr(err && err.message)}`,
    };
  }
}

function sfdcErrorSummary(status, data, text) {
  if (Array.isArray(data)) {
    return data
      .filter((item) => item && typeof item === 'object')
      .map((item) => {
        const code = safeStr(item.errorCode);
        const msg = safeStr(item.message);
        if (code && msg) return `${code}: ${msg}`;
        return msg;
      })
      .filter(Boolean)
      .join('; ');
  }
  if (data && typeof data === 'object') {
    const err = safeStr(data.error);
    const desc = safeStr(data.error_description);
    if (err && desc) return `${err}: ${desc}`;
    if (safeStr(data.message)) return safeStr(data.message);
  }
  return safeStr(text) || `HTTP ${status}`;
}

async function httpRequest({ method, url, headers, params, body, timeoutMs }) {
  const target = new URL(url);
  Object.entries(params || {}).forEach(([key, value]) => target.searchParams.set(key, String(value)));

  if (typeof fetch === 'function') {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    try {
      const resp = await fetch(target.toString(), {
        method,
        headers: headers || {},
        body,
        signal: controller.signal,
      });
      const text = await resp.text();
      let json = null;
      try {
        json = text ? JSON.parse(text) : null;
      } catch (_err) {
        json = null;
      }
      return { status: resp.status, text, json };
    } finally {
      clearTimeout(timer);
    }
  }

  return new Promise((resolve, reject) => {
    const req = https.request(target, { method, headers: headers || {}, timeout: timeoutMs }, (res) => {
      const chunks = [];
      res.on('data', (chunk) => chunks.push(chunk));
      res.on('end', () => {
        const text = Buffer.concat(chunks).toString('utf8');
        let json = null;
        try {
          json = text ? JSON.parse(text) : null;
        } catch (_err) {
          json = null;
        }
        resolve({ status: res.statusCode || 0, text, json });
      });
    });
    req.on('timeout', () => req.destroy(new Error('timed_out')));
    req.on('error', reject);
    if (body) req.write(body);
    req.end();
  });
}

async function callOnce(name, method, url, options) {
  try {
    const payload =
      options.jsonBody != null ? Buffer.from(JSON.stringify(options.jsonBody), 'utf8') : options.dataBody != null ? Buffer.from(String(options.dataBody), 'utf8') : undefined;
    const resp = await httpRequest({
      method,
      url,
      headers: options.headers,
      params: options.params,
      body: payload,
      timeoutMs: options.timeoutMs,
    });
    options.http[name] = resp.status || 'NO_RESP';
    return { resp, err: null };
  } catch (err) {
    const message = safeStr(err && err.message);
    options.http[name] = message === 'timed_out' || message.toLowerCase().includes('abort') ? 'Timed_out' : 'Request_error';
    return { resp: null, err: message === 'timed_out' || message.toLowerCase().includes('abort') ? 'REQUEST -> Timeout' : `REQUEST -> ${message}` };
  }
}

function sfdcBase(instanceUrl, apiVersion) {
  return `${String(instanceUrl).replace(/\/+$/, '')}/services/data/${apiVersion}`;
}

function sfdcHeaders(accessToken) {
  return {
    Authorization: `Bearer ${accessToken}`,
    'Content-Type': 'application/json',
    Accept: 'application/json',
  };
}

async function sfdcQueryOne({ instanceUrl, apiVersion, accessToken, soql, httpStatuses, name, timeoutMs }) {
  const url = `${sfdcBase(instanceUrl, apiVersion)}/query`;
  const { resp, err } = await callOnce(name, 'GET', url, {
    http: httpStatuses,
    headers: sfdcHeaders(accessToken),
    params: { q: soql },
    timeoutMs,
  });
  if (err || !resp) return { record: null, err: err || 'No response' };
  if (resp.status !== 200) return { record: null, err: sfdcErrorSummary(resp.status, resp.json, resp.text) };
  const records = (resp.json && resp.json.records) || [];
  return { record: records.length ? records[0] : null, err: null };
}

async function getSalesforceAccessToken(httpStatuses) {
  const loginUrl =
    envFirst(['salesforce_login_url', 'SFDC_LOGIN_URL', 'SALESFORCE_LOGIN_URL', 'SF_LOGIN_AUD', 'SF_LOGIN_URL']) || DEFAULT_LOGIN_URL;
  const aud = String(loginUrl).replace(/\/+$/, '');
  const clientId = envFirst(SF_PROD_CONSUMER_KEY_SECRET);
  const username = SF_PROD_USERNAME;

  if (!clientId) {
    httpStatuses.sfdc_auth = 'NO_RESP';
    return { instanceUrl: null, accessToken: null, meta: { auth_method: 'jwt_bearer' }, err: `Missing ${SF_PROD_CONSUMER_KEY_SECRET}` };
  }

  const { keyObject, meta: keyMeta, error: keyErr } = getPrivateKeyFromSecrets(httpStatuses);
  if (keyErr || !keyObject) {
    httpStatuses.sfdc_auth = httpStatuses.sfdc_auth || 'NO_RESP';
    return { instanceUrl: null, accessToken: null, meta: { auth_method: 'jwt_bearer', ...keyMeta }, err: keyErr || 'Missing private key' };
  }

  const assertion = buildJwt({ iss: clientId, sub: username, aud, expiresInSec: 180, keyObject });
  const tokenUrl = `${aud}/services/oauth2/token`;
  const body = new URLSearchParams({
    grant_type: 'urn:ietf:params:oauth:grant-type:jwt-bearer',
    assertion,
  }).toString();

  const { resp, err } = await callOnce('sfdc_auth', 'POST', tokenUrl, {
    http: httpStatuses,
    headers: { 'Content-Type': 'application/x-www-form-urlencoded', Accept: 'application/json' },
    dataBody: body,
    timeoutMs: 5000,
  });
  if (err || !resp) return { instanceUrl: null, accessToken: null, meta: { auth_method: 'jwt_bearer', ...keyMeta }, err: err || 'No response' };
  if (resp.status !== 200) return { instanceUrl: null, accessToken: null, meta: { auth_method: 'jwt_bearer', ...keyMeta }, err: sfdcErrorSummary(resp.status, resp.json, resp.text) };

  const accessToken = safeStr(resp.json && resp.json.access_token);
  const instanceUrl = safeStr(resp.json && resp.json.instance_url);
  if (!accessToken || !instanceUrl) {
    return { instanceUrl: null, accessToken: null, meta: { auth_method: 'jwt_bearer', ...keyMeta }, err: 'Token response missing access_token/instance_url' };
  }
  return { instanceUrl, accessToken, meta: { auth_method: 'jwt_bearer', ...keyMeta }, err: null };
}

function blankOutputs() {
  return {
    membership_id: '',
    m_id_known: 'no',
    m_id_status: '',
    membership_status: '',
    operation: '',
    lock_error: 'false',
    error: '',
    error_message: '',
    error_state: '1',
    http: '{}',
    http_message: '{}',
    hs_delegate_id: '',
    level: 'INFO',
    log: '{}',
    other: '{}',
    salesforce_campaign_id: '',
    salesforce_campaign_member_status: '',
    salesforce_campaign_membership_id: '',
    salesforcecontactid: '',
    salesforceleadid: '',
    email: '',
    workflow_action: THIS_ACTION,
    workflow_name: WORKFLOW_NAME,
  };
}

function finalize(outputs, payload) {
  const httpMessage = payload.httpMessage || deriveHttpMessage(payload.httpStatuses, {});
  outputs.m_id_known = outputs.membership_id ? 'yes' : 'no';
  outputs.m_id_status = outputs.salesforce_campaign_member_status || '';
  outputs.workflow_action = payload.actionName || THIS_ACTION;
  outputs.workflow_name = payload.workflowName || WORKFLOW_NAME;
  outputs.level = payload.level;
  outputs.error_state = String(payload.errorState);
  outputs.error_message = safeStr(payload.errorMessage || '');
  outputs.http = jsonCompact(payload.httpStatuses);
  outputs.http_message = jsonCompact(httpMessage);
  outputs.other = jsonCompact(payload.otherPayload || {});

  const logPayload = {
    workflow_action: outputs.workflow_action,
    level: outputs.level,
    error_state: outputs.error_state,
    workflow_name: outputs.workflow_name,
    hs_delegate_id: outputs.hs_delegate_id,
    salesforce_campaign_id: outputs.salesforce_campaign_id,
    salesforce_campaign_membership_id: outputs.salesforce_campaign_membership_id,
    membership_id: outputs.membership_id,
    membership_status: outputs.membership_status,
    salesforce_campaign_member_status: outputs.salesforce_campaign_member_status,
    salesforcecontactid: outputs.salesforcecontactid,
    salesforceleadid: outputs.salesforceleadid,
    email: outputs.email,
    error: { http: payload.httpStatuses, http_message: httpMessage },
    operation: outputs.operation || safeStr(payload.otherPayload && payload.otherPayload.operation),
    action_variant: ACTION_VARIANT,
  };
  if (payload.otherPayload && Object.prototype.hasOwnProperty.call(payload.otherPayload, 'lock_error')) {
    logPayload.lock_error = payload.otherPayload.lock_error;
  }
  outputs.log = jsonCompact(logPayload);
  return { outputFields: selectOutputFields(outputs) };
}

function isLockError(message) {
  return String(message || '').includes('UNABLE_TO_LOCK_ROW');
}

async function core(event) {
  const inputs = (event && event.inputFields) || {};
  const hsDelegateId = safeStr(inputs.hs_delegate_id);
  const campaignId = safeStr(inputs.salesforce_campaign_id);
  const registrationStatus = norm(inputs.registration_status);
  const desiredStatus = desiredStatusFromRegistrationStatus(registrationStatus);
  const membershipIdIn = safeStr(inputs.salesforce_campaign_membership_id);
  const salesforcecontactid = safeStr(inputs.salesforcecontactid);
  const salesforceleadid = safeStr(inputs.salesforceleadid);
  const email = safeStr(inputs.email);

  const outputs = blankOutputs();
  outputs.hs_delegate_id = hsDelegateId;
  outputs.salesforce_campaign_id = campaignId;
  outputs.salesforce_campaign_member_status = desiredStatus;
  outputs.salesforce_campaign_membership_id = membershipIdIn;
  outputs.salesforcecontactid = salesforcecontactid;
  outputs.salesforceleadid = salesforceleadid;
  outputs.email = email;

  const httpStatuses = {};
  const otherPayload = {
    operation: 'failed',
    action_variant: ACTION_VARIANT,
    auth_method: '',
    api_version: sfdcApiVersion(),
    registration_status: registrationStatus,
    desired_status: desiredStatus,
  };

  const finish = (payload) => finalize(outputs, { ...payload, otherPayload });

  if (!hsDelegateId) httpStatuses.input_hs_delegate_id = 'NO_RESP';
  if (!campaignId) httpStatuses.input_salesforce_campaign_id = 'NO_RESP';
  if (!desiredStatus) {
    httpStatuses.input_registration_status = 'INVALID';
  }
  if (salesforcecontactid && salesforceleadid) httpStatuses.input_salesforce_ids = 'INVALID';
  if (!salesforcecontactid && !salesforceleadid) httpStatuses.input_salesforce_ids = 'NO_RESP';
  if (Object.keys(httpStatuses).length) {
    return finish({
      actionName: THIS_ACTION,
      level: 'ERROR',
      errorState: 1,
      httpStatuses,
      httpMessage: deriveHttpMessage(httpStatuses, {
        input_registration_status: "registration_status must be blank, 'confirmed', or 'attended'",
        input_salesforce_ids: 'Provide exactly one of salesforcecontactid or salesforceleadid',
      }),
      errorMessage: 'Missing or invalid inputs',
    });
  }

  const personField = salesforcecontactid ? 'ContactId' : 'LeadId';
  const personId = salesforcecontactid || salesforceleadid;
  otherPayload.person_field = personField;
  otherPayload.person_id = personId;

  const { instanceUrl, accessToken, meta, err: authErr } = await getSalesforceAccessToken(httpStatuses);
  Object.assign(otherPayload, meta || {});
  otherPayload.auth_method = (meta && meta.auth_method) || '';
  if (authErr || !instanceUrl || !accessToken) {
    return finish({
      actionName: THIS_ACTION,
      level: 'ERROR',
      errorState: 1,
      httpStatuses,
      httpMessage: deriveHttpMessage(httpStatuses, { sfdc_auth: authErr || 'Missing Salesforce auth' }),
      errorMessage: 'Salesforce authentication failed',
    });
  }

  const apiVersion = otherPayload.api_version;
  const existing = await sfdcQueryOne({
    instanceUrl,
    apiVersion,
    accessToken,
    soql: `SELECT Id, Status, CampaignId, ContactId, LeadId FROM CampaignMember WHERE CampaignId = '${campaignId}' AND ${personField} = '${personId}' LIMIT 1`,
    httpStatuses,
    name: 'sfdc_query_existing',
    timeoutMs: 4000,
  });
  if (existing.err) {
    return finish({
      actionName: THIS_ACTION,
      level: 'ERROR',
      errorState: 1,
      httpStatuses,
      httpMessage: deriveHttpMessage(httpStatuses, { sfdc_query_existing: existing.err }),
      errorMessage: 'Unable to query CampaignMember',
    });
  }

  if (existing.record) {
    outputs.membership_id = safeStr(existing.record.Id);
    outputs.membership_status = safeStr(existing.record.Status);
    otherPayload.current_status = outputs.membership_status;
    if (norm(outputs.membership_status) === norm(desiredStatus)) {
      outputs.operation = 'skipped';
      otherPayload.operation = 'skipped';
      return finish({ actionName: THIS_ACTION, level: 'INFO', errorState: 0, httpStatuses });
    }
    outputs.operation = 'found_needs_patch';
    otherPayload.operation = 'found_needs_patch';
    otherPayload.needs_patch = true;
    return finish({ actionName: THIS_ACTION, level: 'INFO', errorState: 0, httpStatuses });
  }

  const createResp = await callOnce('sfdc_create_campaign_member', 'POST', `${sfdcBase(instanceUrl, apiVersion)}/sobjects/CampaignMember`, {
    http: httpStatuses,
    headers: sfdcHeaders(accessToken),
    jsonBody: { CampaignId: campaignId, [personField]: personId, Status: desiredStatus },
    timeoutMs: 5000,
  });
  if (createResp.err || !createResp.resp || ![200, 201, 204].includes(createResp.resp.status)) {
    const override =
      createResp.err ||
      sfdcErrorSummary(createResp.resp ? createResp.resp.status : 0, createResp.resp ? createResp.resp.json : null, createResp.resp ? createResp.resp.text : '');
    if (isLockError(override)) {
      outputs.lock_error = 'true';
      outputs.operation = 'lock_error';
      otherPayload.lock_error = true;
      otherPayload.operation = 'lock_error';
      return finish({
        actionName: THIS_ACTION,
        level: 'WARN',
        errorState: 1,
        httpStatuses,
        httpMessage: deriveHttpMessage(httpStatuses, { sfdc_create_campaign_member: override }),
        errorMessage: 'Salesforce POST failed with lock error',
      });
    }
    return finish({
      actionName: THIS_ACTION,
      level: 'ERROR',
      errorState: 1,
      httpStatuses,
      httpMessage: deriveHttpMessage(httpStatuses, { sfdc_create_campaign_member: override }),
      errorMessage: 'Salesforce POST failed',
    });
  }

  outputs.membership_id = safeStr(createResp.resp.json && createResp.resp.json.id);
  if (!outputs.membership_id) {
    const fallback = await sfdcQueryOne({
      instanceUrl,
      apiVersion,
      accessToken,
      soql: `SELECT Id FROM CampaignMember WHERE CampaignId = '${campaignId}' AND ${personField} = '${personId}' LIMIT 1`,
      httpStatuses,
      name: 'sfdc_query_post_create',
      timeoutMs: 4000,
    });
    outputs.membership_id = safeStr(fallback.record && fallback.record.Id);
  }
  if (!outputs.membership_id) {
    return finish({
      actionName: THIS_ACTION,
      level: 'ERROR',
      errorState: 1,
      httpStatuses,
      httpMessage: deriveHttpMessage(httpStatuses, { sfdc_create_campaign_member: 'Created but could not locate id' }),
      errorMessage: 'CampaignMember created but id not found',
    });
  }

  const verified = await sfdcQueryOne({
    instanceUrl,
    apiVersion,
    accessToken,
    soql: `SELECT Id, Status FROM CampaignMember WHERE Id = '${outputs.membership_id}' LIMIT 1`,
    httpStatuses,
    name: 'sfdc_query_verify',
    timeoutMs: 4000,
  });
  if (verified.err || !verified.record) {
    return finish({
      actionName: THIS_ACTION,
      level: 'ERROR',
      errorState: 1,
      httpStatuses,
      httpMessage: deriveHttpMessage(httpStatuses, { sfdc_query_verify: verified.err || 'No CampaignMember record' }),
      errorMessage: 'Unable to verify CampaignMember after POST',
    });
  }

  outputs.membership_status = safeStr(verified.record.Status);
  outputs.operation = 'created';
  otherPayload.operation = 'created';
  otherPayload.verified_status = outputs.membership_status;
  if (norm(outputs.membership_status) !== norm(desiredStatus)) {
    httpStatuses.sfdc_verify_status = 'INVALID';
    return finish({
      actionName: THIS_ACTION,
      level: 'ERROR',
      errorState: 1,
      httpStatuses,
      httpMessage: deriveHttpMessage(httpStatuses, {
        sfdc_verify_status: `Status mismatch (wanted='${desiredStatus}', got='${outputs.membership_status}')`,
      }),
      errorMessage: 'CampaignMember status did not persist (likely invalid status for campaign)',
    });
  }

  return finish({ actionName: THIS_ACTION, level: 'INFO', errorState: 0, httpStatuses });
}

exports.main = async (event, callback) => {
  try {
    callback(await core(event || {}));
  } catch (err) {
    const outputs = blankOutputs();
    const httpStatuses = { uncaught_exception: 'Request_error' };
    callback(
      finalize(outputs, {
        actionName: THIS_ACTION,
        level: 'ERROR',
        errorState: 1,
        httpStatuses,
        httpMessage: deriveHttpMessage(httpStatuses, { uncaught_exception: safeStr(err && err.message ? err.message : err) }),
        otherPayload: { operation: 'failed', action_variant: ACTION_VARIANT },
        errorMessage: 'Unhandled exception in new_delegate_record_CCA1',
      })
    );
  }
};

exports._internal = {
  core,
  getPrivateKeyFromSecrets,
  getSalesforceAccessToken,
  blankOutputs,
  finalize,
};

/*
 * Masks delegate workflow fields and ships a Grafana Loki log line for the preceding action result.
 * Branch before: Run after the preceding workflow action emits loggable fields for this delegate record path.
 * Branch after: Branch only on logger result: dry run, logged successfully, or logging error.
 * Expected inputs: upstream workflow fields via event.inputFields limited to log, http, http_message, and other.
 * Expected outputs: logged, simulated, payload (dry run only), logging_http_status, error.
 */
const https = require('https');
const { URL } = require('url');

const DEFAULT_ACTION = 'new_delegate_record_CCA1';
const WORKFLOW_NAME = 'Delegate New > New SFDC Campaign member';
const GRAFANA_ENV = 'prod';
const JOB_NAME = 'swoogo_sfdc_campaign';
const LOKI_ENDPOINT = (process.env.LOKI_URL || process.env.grafana_url || 'https://logs-prod-012.grafana.net/loki/api/v1/push').trim();
const EMAIL_RE = /([A-Za-z0-9._%+-]+)@([A-Za-z0-9.-]+\.[A-Za-z]{2,})/g;

function safeJsonParse(value, fallback) {
  if (!value) return fallback;
  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      return parsed && typeof parsed === 'object' ? parsed : fallback;
    } catch (_err) {
      return fallback;
    }
  }
  return typeof value === 'object' ? value : fallback;
}

function maskLocal(local) {
  const value = String(local || '');
  const first = value.charAt(0) || 'a';
  const last = value.charAt(value.length - 1) || first;
  return `${first}***${last}`;
}

function maskEmailString(value) {
  return String(value || '').replace(EMAIL_RE, (_match, local, domain) => `${maskLocal(local)}@${domain}`);
}

function maskDeep(value) {
  if (Array.isArray(value)) return value.map((item) => maskDeep(item));
  if (value && typeof value === 'object') {
    return Object.keys(value).reduce((acc, key) => {
      acc[key] = maskDeep(value[key]);
      return acc;
    }, {});
  }
  if (typeof value === 'string') return maskEmailString(value);
  return value;
}

function buildLogLine(inputs) {
  const parsedLog = safeJsonParse(inputs.log, {});
  const payload = {
    workflow_action: parsedLog.workflow_action || inputs.workflow_action || DEFAULT_ACTION,
    workflow_name: parsedLog.workflow_name || inputs.workflow_name || WORKFLOW_NAME,
    level: parsedLog.level || inputs.level || 'INFO',
    error_state: parsedLog.error_state || inputs.error_state || '0',
    hs_delegate_id: parsedLog.hs_delegate_id || inputs.hs_delegate_id || '',
    salesforce_campaign_id: parsedLog.salesforce_campaign_id || inputs.salesforce_campaign_id || '',
    salesforce_campaign_membership_id:
      parsedLog.salesforce_campaign_membership_id || inputs.salesforce_campaign_membership_id || '',
    membership_id: parsedLog.membership_id || inputs.membership_id || '',
    membership_status: parsedLog.membership_status || inputs.membership_status || '',
    salesforce_campaign_member_status:
      parsedLog.salesforce_campaign_member_status || inputs.salesforce_campaign_member_status || '',
    salesforcecontactid: parsedLog.salesforcecontactid || inputs.salesforcecontactid || '',
    salesforceleadid: parsedLog.salesforceleadid || inputs.salesforceleadid || '',
    email: parsedLog.email || inputs.email || '',
    error: {
      http: (parsedLog.error && parsedLog.error.http) || safeJsonParse(inputs.http, {}),
      http_message: (parsedLog.error && parsedLog.error.http_message) || safeJsonParse(inputs.http_message, {}),
    },
    other: safeJsonParse(inputs.other, parsedLog.other || {}),
  };
  payload.campaign_member_id = payload.membership_id || payload.salesforce_campaign_membership_id || '';
  if (parsedLog.operation || payload.other.operation) payload.operation = parsedLog.operation || payload.other.operation;
  if (parsedLog.action_variant || payload.other.action_variant) payload.action_variant = parsedLog.action_variant || payload.other.action_variant;
  if (payload.other.lock_error !== undefined) payload.lock_error = payload.other.lock_error;
  return JSON.stringify(maskDeep(payload));
}

async function postJson(url, payload, user, token) {
  const target = new URL(url);
  const body = JSON.stringify(payload);
  const auth = `Basic ${Buffer.from(`${user}:${token}`).toString('base64')}`;

  if (typeof fetch === 'function') {
    const resp = await fetch(target.toString(), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: auth },
      body,
    });
    const text = await resp.text();
    if (resp.status < 200 || resp.status >= 300) throw new Error(text || `HTTP ${resp.status}`);
    return { status: resp.status };
  }

  return new Promise((resolve, reject) => {
    const req = https.request(
      target,
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(body),
          Authorization: auth,
        },
      },
      (res) => {
        const chunks = [];
        res.on('data', (chunk) => chunks.push(chunk));
        res.on('end', () => {
          const text = Buffer.concat(chunks).toString('utf8');
          if ((res.statusCode || 0) < 200 || (res.statusCode || 0) >= 300) {
            reject(new Error(text || `HTTP ${res.statusCode || 0}`));
            return;
          }
          resolve({ status: res.statusCode || 0 });
        });
      }
    );
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

exports.main = async (event, callback) => {
  try {
    const user = (process.env.grafana_user || process.env.GRAFANA_USER || '').trim();
    const token = (process.env.grafana_token || process.env.GRAFANA_TOKEN || '').trim();
    if (!user || !token) throw new Error('Missing grafana_user or grafana_token environment variables.');

    const payload = {
      streams: [
        {
          stream: {
            service_name: 'hubspot',
            environment: GRAFANA_ENV,
            process: 'workflow',
            team: 'marketing_technology',
            job: JOB_NAME,
          },
          values: [[`${Date.now()}000000`, buildLogLine((event && event.inputFields) || {})]],
        },
      ],
    };

    if (String(process.env.GRAFANA_DRY_RUN || '').trim() === '1') {
      callback({ outputFields: { logged: false, simulated: true, payload } });
      return;
    }

    const res = await postJson(LOKI_ENDPOINT, payload, user, token);
    callback({ outputFields: { logged: true, simulated: false, logging_http_status: res.status } });
  } catch (error) {
    callback({
      outputFields: {
        logged: false,
        error: String(error && error.message ? error.message : error),
      },
    });
  }
};

/*
 * Authenticates to Salesforce, verifies an existing CampaignMember, patches its status when needed, and returns verified membership details for the delegate workflow.
 * Branch before: Run only when a CampaignMember already exists and needs a status patch, or when retrying a failed patch.
 * Branch after: Route by output state: skipped, patched, lock_error, or error.
 * Expected inputs: hs_delegate_id, salesforce_campaign_membership_id, registration_status, optional salesforce_campaign_id, salesforcecontactid, salesforceleadid, email.
 * Expected outputs: log, http, http_message, other, lock_error.
 */
const crypto = require('crypto');
const https = require('https');
const { URL } = require('url');

const THIS_ACTION = 'new_delegate_record_CCA2';
const WORKFLOW_NAME = 'Delegate New > New SFDC Campaign member';
const ACTION_VARIANT = 'patch';
const DEFAULT_LOGIN_URL = 'https://login.salesforce.com';
const DEFAULT_API_VERSION = 'v62.0';
const SF_PROD_CONSUMER_KEY_SECRET = 'SF_CONSUMER_KEY_PROD';
const SF_PROD_USERNAME = 'hubspot.integration@nanoporetech.com';
const SF_PROD_JWT_PART_NAMES = ['SF_JWT_PART_01', 'SF_JWT_PART_02', 'SF_JWT_PART_03'];
const EXPOSED_OUTPUT_FIELDS = ['log', 'http', 'http_message', 'other', 'lock_error'];

function safeStr(value) {
  return String(value == null ? '' : value).trim();
}

function norm(value) {
  return safeStr(value).toLowerCase();
}

function desiredStatusFromRegistrationStatus(value) {
  const normalized = norm(value);
  if (!normalized) return 'Registered';
  if (normalized === 'confirmed') return 'Registered';
  if (normalized === 'attended') return 'Attended';
  return '';
}

function jsonCompact(obj) {
  return JSON.stringify(obj == null ? {} : obj);
}

function selectOutputFields(outputs) {
  return EXPOSED_OUTPUT_FIELDS.reduce((acc, key) => {
    acc[key] = outputs[key];
    return acc;
  }, {});
}

function friendly(value) {
  const map = {
    200: 'OK',
    201: 'Created',
    204: 'No content',
    400: 'Bad Request – Your request is wrong',
    401: 'Unauthorized (credentials)',
    403: 'Forbidden (scope)',
    404: 'Not Found',
    405: 'Method Not Allowed',
    408: 'Request timeout',
    409: 'Conflict',
    422: 'Unprocessable entity',
    429: 'Too Many Requests',
    500: 'Internal Server Error',
    502: 'Bad gateway / processing limit met',
    503: 'Service temporarily unavailable',
    504: 'Gateway timeout / processing limit met',
  };
  if (typeof value === 'number') return map[value] || `HTTP ${value}`;
  const text = String(value || '');
  if (text === 'Timed_out') return 'Timeout';
  if (text === 'Request_error') return 'Request error';
  return 'No response';
}

function deriveHttpMessage(httpDict, overrides) {
  const out = {};
  Object.entries(httpDict || {}).forEach(([key, value]) => {
    const asNum = Number(value);
    out[key] = Number.isFinite(asNum) ? friendly(asNum) : friendly(value);
  });
  Object.entries(overrides || {}).forEach(([key, value]) => {
    if (value !== undefined && value !== null && String(value).trim() !== '') out[key] = String(value);
  });
  return out;
}

function envFirst(keys) {
  const list = Array.isArray(keys) ? keys : [keys];
  for (const key of list) {
    const raw = process.env[key];
    if (raw == null) continue;
    const value = String(raw).trim();
    if (value) return value;
  }
  return '';
}

function sfdcApiVersion() {
  const raw = envFirst(['salesforce_api_version', 'SFDC_API_VERSION', 'SALESFORCE_API_VERSION']) || DEFAULT_API_VERSION;
  const value = raw.replace(/^\//, '').trim();
  if (!value) return DEFAULT_API_VERSION;
  if (/^\d/.test(value)) return `v${value}`;
  return value;
}

function base64url(input) {
  const buf = Buffer.isBuffer(input) ? input : Buffer.from(String(input), 'utf8');
  return buf.toString('base64').replace(/=/g, '').replace(/\+/g, '-').replace(/\//g, '_');
}

function buildJwt({ iss, sub, aud, expiresInSec, keyObject }) {
  const now = Math.floor(Date.now() / 1000);
  const header = { alg: 'RS256', typ: 'JWT' };
  const payload = { iss, sub, aud, iat: now, exp: now + expiresInSec };
  const signingInput = `${base64url(jsonCompact(header))}.${base64url(jsonCompact(payload))}`;
  const signature = crypto.sign('RSA-SHA256', Buffer.from(signingInput, 'utf8'), keyObject);
  return `${signingInput}.${base64url(signature)}`;
}

function validateBase64String(b64) {
  if (!b64) return { ok: false, reason: 'empty' };
  if (!/^[A-Za-z0-9+/=]+$/.test(b64)) return { ok: false, reason: 'non_base64_chars' };
  if (b64.length % 4 !== 0) return { ok: false, reason: 'length_not_multiple_of_4' };
  return { ok: true };
}

function getPrivateKeyFromSecrets(httpStatuses) {
  const parts = SF_PROD_JWT_PART_NAMES.map((name) => envFirst(name));
  if (parts.some((part) => !part)) {
    httpStatuses.sfdc_key = 'NO_RESP';
    return {
      keyObject: null,
      meta: { key_scheme: 'SF_JWT_PART_prod_3parts', key_parts_expected: SF_PROD_JWT_PART_NAMES.length, key_parts_found: parts.filter(Boolean).length },
      error: 'Missing private key parts',
    };
  }
  const scheme = 'SF_JWT_PART_prod_3parts';

  const b64 = parts.map((item) => String(item).replace(/\s+/g, '')).join('');
  const valid = validateBase64String(b64);
  if (!valid.ok) {
    httpStatuses.sfdc_key = 'INVALID';
    return {
      keyObject: null,
      meta: { key_scheme: scheme, key_parts: parts.length, key_b64_len: b64.length, key_b64_reason: valid.reason },
      error: `Invalid base64 private key (${valid.reason})`,
    };
  }

  let pem = '';
  try {
    pem = Buffer.from(b64, 'base64').toString('utf8');
  } catch (err) {
    httpStatuses.sfdc_key = 'INVALID';
    return {
      keyObject: null,
      meta: { key_scheme: scheme, key_parts: parts.length, key_b64_len: b64.length },
      error: `Key decode failed: ${safeStr(err && err.message)}`,
    };
  }

  if (!pem.startsWith('-----BEGIN')) {
    httpStatuses.sfdc_key = 'INVALID';
    return {
      keyObject: null,
      meta: { key_scheme: scheme, key_parts: parts.length, pem_prefix: pem.slice(0, 20) },
      error: 'Decoded key is not PEM',
    };
  }

  try {
    const keyObject = crypto.createPrivateKey(pem);
    const fingerprint = crypto.createHash('sha256').update(pem).digest('hex').slice(0, 12);
    return {
      keyObject,
      meta: { key_scheme: scheme, key_parts: parts.length, key_b64_len: b64.length, pem_len: pem.length, key_fp: fingerprint },
      error: null,
    };
  } catch (err) {
    httpStatuses.sfdc_key = 'INVALID';
    return {
      keyObject: null,
      meta: { key_scheme: scheme, key_parts: parts.length, pem_len: pem.length },
      error: `PEM parse failed: ${safeStr(err && err.message)}`,
    };
  }
}

function sfdcErrorSummary(status, data, text) {
  if (Array.isArray(data)) {
    return data
      .filter((item) => item && typeof item === 'object')
      .map((item) => {
        const code = safeStr(item.errorCode);
        const msg = safeStr(item.message);
        if (code && msg) return `${code}: ${msg}`;
        return msg;
      })
      .filter(Boolean)
      .join('; ');
  }
  if (data && typeof data === 'object') {
    const err = safeStr(data.error);
    const desc = safeStr(data.error_description);
    if (err && desc) return `${err}: ${desc}`;
    if (safeStr(data.message)) return safeStr(data.message);
  }
  return safeStr(text) || `HTTP ${status}`;
}

async function httpRequest({ method, url, headers, params, body, timeoutMs }) {
  const target = new URL(url);
  Object.entries(params || {}).forEach(([key, value]) => target.searchParams.set(key, String(value)));

  if (typeof fetch === 'function') {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    try {
      const resp = await fetch(target.toString(), {
        method,
        headers: headers || {},
        body,
        signal: controller.signal,
      });
      const text = await resp.text();
      let json = null;
      try {
        json = text ? JSON.parse(text) : null;
      } catch (_err) {
        json = null;
      }
      return { status: resp.status, text, json };
    } finally {
      clearTimeout(timer);
    }
  }

  return new Promise((resolve, reject) => {
    const req = https.request(target, { method, headers: headers || {}, timeout: timeoutMs }, (res) => {
      const chunks = [];
      res.on('data', (chunk) => chunks.push(chunk));
      res.on('end', () => {
        const text = Buffer.concat(chunks).toString('utf8');
        let json = null;
        try {
          json = text ? JSON.parse(text) : null;
        } catch (_err) {
          json = null;
        }
        resolve({ status: res.statusCode || 0, text, json });
      });
    });
    req.on('timeout', () => req.destroy(new Error('timed_out')));
    req.on('error', reject);
    if (body) req.write(body);
    req.end();
  });
}

async function callOnce(name, method, url, options) {
  try {
    const payload =
      options.jsonBody != null ? Buffer.from(JSON.stringify(options.jsonBody), 'utf8') : options.dataBody != null ? Buffer.from(String(options.dataBody), 'utf8') : undefined;
    const resp = await httpRequest({
      method,
      url,
      headers: options.headers,
      params: options.params,
      body: payload,
      timeoutMs: options.timeoutMs,
    });
    options.http[name] = resp.status || 'NO_RESP';
    return { resp, err: null };
  } catch (err) {
    const message = safeStr(err && err.message);
    options.http[name] = message === 'timed_out' || message.toLowerCase().includes('abort') ? 'Timed_out' : 'Request_error';
    return { resp: null, err: message === 'timed_out' || message.toLowerCase().includes('abort') ? 'REQUEST -> Timeout' : `REQUEST -> ${message}` };
  }
}

function sfdcBase(instanceUrl, apiVersion) {
  return `${String(instanceUrl).replace(/\/+$/, '')}/services/data/${apiVersion}`;
}

function sfdcHeaders(accessToken) {
  return {
    Authorization: `Bearer ${accessToken}`,
    'Content-Type': 'application/json',
    Accept: 'application/json',
  };
}

async function sfdcQueryOne({ instanceUrl, apiVersion, accessToken, soql, httpStatuses, name, timeoutMs }) {
  const url = `${sfdcBase(instanceUrl, apiVersion)}/query`;
  const { resp, err } = await callOnce(name, 'GET', url, {
    http: httpStatuses,
    headers: sfdcHeaders(accessToken),
    params: { q: soql },
    timeoutMs,
  });
  if (err || !resp) return { record: null, err: err || 'No response' };
  if (resp.status !== 200) return { record: null, err: sfdcErrorSummary(resp.status, resp.json, resp.text) };
  const records = (resp.json && resp.json.records) || [];
  return { record: records.length ? records[0] : null, err: null };
}

async function getSalesforceAccessToken(httpStatuses) {
  const loginUrl =
    envFirst(['salesforce_login_url', 'SFDC_LOGIN_URL', 'SALESFORCE_LOGIN_URL', 'SF_LOGIN_AUD', 'SF_LOGIN_URL']) || DEFAULT_LOGIN_URL;
  const aud = String(loginUrl).replace(/\/+$/, '');
  const clientId = envFirst(SF_PROD_CONSUMER_KEY_SECRET);
  const username = SF_PROD_USERNAME;

  if (!clientId) {
    httpStatuses.sfdc_auth = 'NO_RESP';
    return { instanceUrl: null, accessToken: null, meta: { auth_method: 'jwt_bearer' }, err: `Missing ${SF_PROD_CONSUMER_KEY_SECRET}` };
  }

  const { keyObject, meta: keyMeta, error: keyErr } = getPrivateKeyFromSecrets(httpStatuses);
  if (keyErr || !keyObject) {
    httpStatuses.sfdc_auth = httpStatuses.sfdc_auth || 'NO_RESP';
    return { instanceUrl: null, accessToken: null, meta: { auth_method: 'jwt_bearer', ...keyMeta }, err: keyErr || 'Missing private key' };
  }

  const assertion = buildJwt({ iss: clientId, sub: username, aud, expiresInSec: 180, keyObject });
  const tokenUrl = `${aud}/services/oauth2/token`;
  const body = new URLSearchParams({
    grant_type: 'urn:ietf:params:oauth:grant-type:jwt-bearer',
    assertion,
  }).toString();

  const { resp, err } = await callOnce('sfdc_auth', 'POST', tokenUrl, {
    http: httpStatuses,
    headers: { 'Content-Type': 'application/x-www-form-urlencoded', Accept: 'application/json' },
    dataBody: body,
    timeoutMs: 5000,
  });
  if (err || !resp) return { instanceUrl: null, accessToken: null, meta: { auth_method: 'jwt_bearer', ...keyMeta }, err: err || 'No response' };
  if (resp.status !== 200) return { instanceUrl: null, accessToken: null, meta: { auth_method: 'jwt_bearer', ...keyMeta }, err: sfdcErrorSummary(resp.status, resp.json, resp.text) };

  const accessToken = safeStr(resp.json && resp.json.access_token);
  const instanceUrl = safeStr(resp.json && resp.json.instance_url);
  if (!accessToken || !instanceUrl) {
    return { instanceUrl: null, accessToken: null, meta: { auth_method: 'jwt_bearer', ...keyMeta }, err: 'Token response missing access_token/instance_url' };
  }
  return { instanceUrl, accessToken, meta: { auth_method: 'jwt_bearer', ...keyMeta }, err: null };
}

function blankOutputs() {
  return {
    membership_id: '',
    membership_status: '',
    operation: '',
    lock_error: 'false',
    error: '',
    error_message: '',
    error_state: '1',
    http: '{}',
    http_message: '{}',
    hs_delegate_id: '',
    level: 'INFO',
    log: '{}',
    other: '{}',
    salesforce_campaign_id: '',
    salesforce_campaign_member_status: '',
    salesforce_campaign_membership_id: '',
    salesforcecontactid: '',
    salesforceleadid: '',
    email: '',
    workflow_action: THIS_ACTION,
    workflow_name: WORKFLOW_NAME,
  };
}

function finalize(outputs, payload) {
  const httpMessage = payload.httpMessage || deriveHttpMessage(payload.httpStatuses, {});
  outputs.workflow_action = payload.actionName || THIS_ACTION;
  outputs.workflow_name = payload.workflowName || WORKFLOW_NAME;
  outputs.level = payload.level;
  outputs.error_state = String(payload.errorState);
  outputs.error_message = safeStr(payload.errorMessage || '');
  outputs.http = jsonCompact(payload.httpStatuses);
  outputs.http_message = jsonCompact(httpMessage);
  outputs.other = jsonCompact(payload.otherPayload || {});

  const logPayload = {
    workflow_action: outputs.workflow_action,
    level: outputs.level,
    error_state: outputs.error_state,
    workflow_name: outputs.workflow_name,
    hs_delegate_id: outputs.hs_delegate_id,
    salesforce_campaign_id: outputs.salesforce_campaign_id,
    salesforce_campaign_membership_id: outputs.salesforce_campaign_membership_id,
    membership_id: outputs.membership_id,
    membership_status: outputs.membership_status,
    salesforce_campaign_member_status: outputs.salesforce_campaign_member_status,
    salesforcecontactid: outputs.salesforcecontactid,
    salesforceleadid: outputs.salesforceleadid,
    email: outputs.email,
    error: { http: payload.httpStatuses, http_message: httpMessage },
    operation: outputs.operation || safeStr(payload.otherPayload && payload.otherPayload.operation),
    action_variant: ACTION_VARIANT,
  };
  if (payload.otherPayload && Object.prototype.hasOwnProperty.call(payload.otherPayload, 'lock_error')) {
    logPayload.lock_error = payload.otherPayload.lock_error;
  }
  outputs.log = jsonCompact(logPayload);
  return { outputFields: selectOutputFields(outputs) };
}

function isLockError(message) {
  return String(message || '').includes('UNABLE_TO_LOCK_ROW');
}

async function core(event) {
  const inputs = (event && event.inputFields) || {};
  const hsDelegateId = safeStr(inputs.hs_delegate_id);
  const campaignId = safeStr(inputs.salesforce_campaign_id);
  const registrationStatus = norm(inputs.registration_status);
  const desiredStatus = desiredStatusFromRegistrationStatus(registrationStatus);
  const membershipIdIn = safeStr(inputs.salesforce_campaign_membership_id);
  const salesforcecontactid = safeStr(inputs.salesforcecontactid);
  const salesforceleadid = safeStr(inputs.salesforceleadid);
  const email = safeStr(inputs.email);

  const outputs = blankOutputs();
  outputs.hs_delegate_id = hsDelegateId;
  outputs.salesforce_campaign_id = campaignId;
  outputs.salesforce_campaign_member_status = desiredStatus;
  outputs.salesforce_campaign_membership_id = membershipIdIn;
  outputs.salesforcecontactid = salesforcecontactid;
  outputs.salesforceleadid = salesforceleadid;
  outputs.email = email;

  const httpStatuses = {};
  const otherPayload = {
    operation: 'failed',
    action_variant: ACTION_VARIANT,
    auth_method: '',
    api_version: sfdcApiVersion(),
    registration_status: registrationStatus,
    desired_status: desiredStatus,
  };

  const finish = (payload) => finalize(outputs, { ...payload, otherPayload });

  if (!hsDelegateId) httpStatuses.input_hs_delegate_id = 'NO_RESP';
  if (!desiredStatus) {
    httpStatuses.input_registration_status = 'INVALID';
  }
  if (!membershipIdIn) httpStatuses.input_salesforce_campaign_membership_id = 'NO_RESP';
  if (Object.keys(httpStatuses).length) {
    return finish({
      actionName: THIS_ACTION,
      level: 'ERROR',
      errorState: 1,
      httpStatuses,
      httpMessage: deriveHttpMessage(httpStatuses, {
        input_registration_status: "registration_status must be blank, 'confirmed', or 'attended'",
      }),
      errorMessage: 'Missing or invalid inputs',
    });
  }

  const { instanceUrl, accessToken, meta, err: authErr } = await getSalesforceAccessToken(httpStatuses);
  Object.assign(otherPayload, meta || {});
  otherPayload.auth_method = (meta && meta.auth_method) || '';
  if (authErr || !instanceUrl || !accessToken) {
    return finish({
      actionName: THIS_ACTION,
      level: 'ERROR',
      errorState: 1,
      httpStatuses,
      httpMessage: deriveHttpMessage(httpStatuses, { sfdc_auth: authErr || 'Missing Salesforce auth' }),
      errorMessage: 'Salesforce authentication failed',
    });
  }

  const apiVersion = otherPayload.api_version;
  outputs.membership_id = membershipIdIn;
  const verified = await sfdcQueryOne({
    instanceUrl,
    apiVersion,
    accessToken,
    soql: `SELECT Id, Status, CampaignId, ContactId, LeadId FROM CampaignMember WHERE Id = '${membershipIdIn}' LIMIT 1`,
    httpStatuses,
    name: 'sfdc_query_verify',
    timeoutMs: 4000,
  });
  if (verified.err || !verified.record) {
    return finish({
      actionName: THIS_ACTION,
      level: 'ERROR',
      errorState: 1,
      httpStatuses,
      httpMessage: deriveHttpMessage(httpStatuses, { sfdc_query_verify: verified.err || 'CampaignMember not found' }),
      errorMessage: 'Unable to verify existing CampaignMember',
    });
  }

  if (campaignId && safeStr(verified.record.CampaignId) && safeStr(verified.record.CampaignId) !== campaignId) {
    httpStatuses.input_salesforce_campaign_id = 'INVALID';
    return finish({
      actionName: THIS_ACTION,
      level: 'ERROR',
      errorState: 1,
      httpStatuses,
      httpMessage: deriveHttpMessage(httpStatuses, {
        input_salesforce_campaign_id: 'Existing CampaignMember does not match CampaignId',
      }),
      errorMessage: 'CampaignMember/Campaign mismatch',
    });
  }

  if (!outputs.salesforcecontactid && verified.record.ContactId) outputs.salesforcecontactid = safeStr(verified.record.ContactId);
  if (!outputs.salesforceleadid && verified.record.LeadId) outputs.salesforceleadid = safeStr(verified.record.LeadId);

  outputs.membership_status = safeStr(verified.record.Status);
  otherPayload.current_status = outputs.membership_status;
  if (norm(outputs.membership_status) === norm(desiredStatus)) {
    outputs.operation = 'skipped';
    otherPayload.operation = 'skipped';
    return finish({ actionName: THIS_ACTION, level: 'INFO', errorState: 0, httpStatuses });
  }

  const patchResp = await callOnce('sfdc_patch_campaign_member', 'PATCH', `${sfdcBase(instanceUrl, apiVersion)}/sobjects/CampaignMember/${membershipIdIn}`, {
    http: httpStatuses,
    headers: sfdcHeaders(accessToken),
    jsonBody: { Status: desiredStatus },
    timeoutMs: 5000,
  });
  if (patchResp.err || !patchResp.resp || patchResp.resp.status !== 204) {
    const override =
      patchResp.err ||
      sfdcErrorSummary(patchResp.resp ? patchResp.resp.status : 0, patchResp.resp ? patchResp.resp.json : null, patchResp.resp ? patchResp.resp.text : '');
    if (isLockError(override)) {
      outputs.lock_error = 'true';
      outputs.operation = 'lock_error';
      otherPayload.lock_error = true;
      otherPayload.operation = 'lock_error';
      return finish({
        actionName: THIS_ACTION,
        level: 'WARN',
        errorState: 1,
        httpStatuses,
        httpMessage: deriveHttpMessage(httpStatuses, { sfdc_patch_campaign_member: override }),
        errorMessage: 'Salesforce PATCH failed with lock error',
      });
    }
    return finish({
      actionName: THIS_ACTION,
      level: 'ERROR',
      errorState: 1,
      httpStatuses,
      httpMessage: deriveHttpMessage(httpStatuses, { sfdc_patch_campaign_member: override }),
      errorMessage: 'Salesforce PATCH failed',
    });
  }

  const postPatch = await sfdcQueryOne({
    instanceUrl,
    apiVersion,
    accessToken,
    soql: `SELECT Id, Status FROM CampaignMember WHERE Id = '${membershipIdIn}' LIMIT 1`,
    httpStatuses,
    name: 'sfdc_query_verify_after_patch',
    timeoutMs: 4000,
  });
  if (postPatch.err || !postPatch.record) {
    return finish({
      actionName: THIS_ACTION,
      level: 'ERROR',
      errorState: 1,
      httpStatuses,
      httpMessage: deriveHttpMessage(httpStatuses, {
        sfdc_query_verify_after_patch: postPatch.err || 'No CampaignMember record',
      }),
      errorMessage: 'Unable to verify CampaignMember after PATCH',
    });
  }

  outputs.membership_status = safeStr(postPatch.record.Status);
  outputs.operation = 'patched';
  otherPayload.operation = 'patched';
  otherPayload.verified_status = outputs.membership_status;
  if (norm(outputs.membership_status) !== norm(desiredStatus)) {
    httpStatuses.sfdc_verify_status = 'INVALID';
    return finish({
      actionName: THIS_ACTION,
      level: 'ERROR',
      errorState: 1,
      httpStatuses,
      httpMessage: deriveHttpMessage(httpStatuses, {
        sfdc_verify_status: `Status mismatch (wanted='${desiredStatus}', got='${outputs.membership_status}')`,
      }),
      errorMessage: 'CampaignMember status did not persist (likely invalid status for campaign)',
    });
  }

  return finish({ actionName: THIS_ACTION, level: 'INFO', errorState: 0, httpStatuses });
}

exports.main = async (event, callback) => {
  try {
    callback(await core(event || {}));
  } catch (err) {
    const outputs = blankOutputs();
    const httpStatuses = { uncaught_exception: 'Request_error' };
    callback(
      finalize(outputs, {
        actionName: THIS_ACTION,
        level: 'ERROR',
        errorState: 1,
        httpStatuses,
        httpMessage: deriveHttpMessage(httpStatuses, { uncaught_exception: safeStr(err && err.message ? err.message : err) }),
        otherPayload: { operation: 'failed', action_variant: ACTION_VARIANT },
        errorMessage: 'Unhandled exception in new_delegate_record_CCA2',
      })
    );
  }
};

exports._internal = {
  core,
  getPrivateKeyFromSecrets,
  getSalesforceAccessToken,
  blankOutputs,
  finalize,
};

/*
 * Masks delegate workflow fields and ships a Grafana Loki log line for the preceding action result.
 * Branch before: Run after the preceding workflow action emits loggable fields for this delegate record path.
 * Branch after: Branch only on logger result: dry run, logged successfully, or logging error.
 * Expected inputs: upstream workflow fields via event.inputFields limited to log, http, http_message, and other.
 * Expected outputs: logged, simulated, payload (dry run only), logging_http_status, error.
 */
const https = require('https');
const { URL } = require('url');

const DEFAULT_ACTION = 'new_delegate_record_CCA2';
const WORKFLOW_NAME = 'Delegate New > New SFDC Campaign member';
const GRAFANA_ENV = 'prod';
const JOB_NAME = 'swoogo_sfdc_campaign';
const LOKI_ENDPOINT = (process.env.LOKI_URL || process.env.grafana_url || 'https://logs-prod-012.grafana.net/loki/api/v1/push').trim();
const EMAIL_RE = /([A-Za-z0-9._%+-]+)@([A-Za-z0-9.-]+\.[A-Za-z]{2,})/g;

function safeJsonParse(value, fallback) {
  if (!value) return fallback;
  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      return parsed && typeof parsed === 'object' ? parsed : fallback;
    } catch (_err) {
      return fallback;
    }
  }
  return typeof value === 'object' ? value : fallback;
}

function maskLocal(local) {
  const value = String(local || '');
  const first = value.charAt(0) || 'a';
  const last = value.charAt(value.length - 1) || first;
  return `${first}***${last}`;
}

function maskEmailString(value) {
  return String(value || '').replace(EMAIL_RE, (_match, local, domain) => `${maskLocal(local)}@${domain}`);
}

function maskDeep(value) {
  if (Array.isArray(value)) return value.map((item) => maskDeep(item));
  if (value && typeof value === 'object') {
    return Object.keys(value).reduce((acc, key) => {
      acc[key] = maskDeep(value[key]);
      return acc;
    }, {});
  }
  if (typeof value === 'string') return maskEmailString(value);
  return value;
}

function buildLogLine(inputs) {
  const parsedLog = safeJsonParse(inputs.log, {});
  const payload = {
    workflow_action: parsedLog.workflow_action || inputs.workflow_action || DEFAULT_ACTION,
    workflow_name: parsedLog.workflow_name || inputs.workflow_name || WORKFLOW_NAME,
    level: parsedLog.level || inputs.level || 'INFO',
    error_state: parsedLog.error_state || inputs.error_state || '0',
    hs_delegate_id: parsedLog.hs_delegate_id || inputs.hs_delegate_id || '',
    salesforce_campaign_id: parsedLog.salesforce_campaign_id || inputs.salesforce_campaign_id || '',
    salesforce_campaign_membership_id:
      parsedLog.salesforce_campaign_membership_id || inputs.salesforce_campaign_membership_id || '',
    membership_id: parsedLog.membership_id || inputs.membership_id || '',
    membership_status: parsedLog.membership_status || inputs.membership_status || '',
    salesforce_campaign_member_status:
      parsedLog.salesforce_campaign_member_status || inputs.salesforce_campaign_member_status || '',
    salesforcecontactid: parsedLog.salesforcecontactid || inputs.salesforcecontactid || '',
    salesforceleadid: parsedLog.salesforceleadid || inputs.salesforceleadid || '',
    email: parsedLog.email || inputs.email || '',
    error: {
      http: (parsedLog.error && parsedLog.error.http) || safeJsonParse(inputs.http, {}),
      http_message: (parsedLog.error && parsedLog.error.http_message) || safeJsonParse(inputs.http_message, {}),
    },
    other: safeJsonParse(inputs.other, parsedLog.other || {}),
  };
  payload.campaign_member_id = payload.membership_id || payload.salesforce_campaign_membership_id || '';
  if (parsedLog.operation || payload.other.operation) payload.operation = parsedLog.operation || payload.other.operation;
  if (parsedLog.action_variant || payload.other.action_variant) payload.action_variant = parsedLog.action_variant || payload.other.action_variant;
  if (payload.other.lock_error !== undefined) payload.lock_error = payload.other.lock_error;
  return JSON.stringify(maskDeep(payload));
}

async function postJson(url, payload, user, token) {
  const target = new URL(url);
  const body = JSON.stringify(payload);
  const auth = `Basic ${Buffer.from(`${user}:${token}`).toString('base64')}`;

  if (typeof fetch === 'function') {
    const resp = await fetch(target.toString(), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: auth },
      body,
    });
    const text = await resp.text();
    if (resp.status < 200 || resp.status >= 300) throw new Error(text || `HTTP ${resp.status}`);
    return { status: resp.status };
  }

  return new Promise((resolve, reject) => {
    const req = https.request(
      target,
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(body),
          Authorization: auth,
        },
      },
      (res) => {
        const chunks = [];
        res.on('data', (chunk) => chunks.push(chunk));
        res.on('end', () => {
          const text = Buffer.concat(chunks).toString('utf8');
          if ((res.statusCode || 0) < 200 || (res.statusCode || 0) >= 300) {
            reject(new Error(text || `HTTP ${res.statusCode || 0}`));
            return;
          }
          resolve({ status: res.statusCode || 0 });
        });
      }
    );
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

exports.main = async (event, callback) => {
  try {
    const user = (process.env.grafana_user || process.env.GRAFANA_USER || '').trim();
    const token = (process.env.grafana_token || process.env.GRAFANA_TOKEN || '').trim();
    if (!user || !token) throw new Error('Missing grafana_user or grafana_token environment variables.');

    const payload = {
      streams: [
        {
          stream: {
            service_name: 'hubspot',
            environment: GRAFANA_ENV,
            process: 'workflow',
            team: 'marketing_technology',
            job: JOB_NAME,
          },
          values: [[`${Date.now()}000000`, buildLogLine((event && event.inputFields) || {})]],
        },
      ],
    };

    if (String(process.env.GRAFANA_DRY_RUN || '').trim() === '1') {
      callback({ outputFields: { logged: false, simulated: true, payload } });
      return;
    }

    const res = await postJson(LOKI_ENDPOINT, payload, user, token);
    callback({ outputFields: { logged: true, simulated: false, logging_http_status: res.status } });
  } catch (error) {
    callback({
      outputFields: {
        logged: false,
        error: String(error && error.message ? error.message : error),
      },
    });
  }
};

/*
 * Retries Salesforce CampaignMember creation after a failed post, then returns member details or patch guidance for the delegate workflow.
 * Branch before: None unless upstream routing already selected the create or retry-create path for this delegate.
 * Branch after: Route by output state: skipped, found_needs_patch, created, lock_error, or error.
 * Expected inputs: hs_delegate_id, salesforce_campaign_id, registration_status, exactly one of salesforcecontactid or salesforceleadid, optional salesforce_campaign_membership_id, email.
 * Expected outputs: log, http, http_message, other, membership_id, operation.
 */
const crypto = require('crypto');
const https = require('https');
const { URL } = require('url');

const THIS_ACTION = 'new_delegate_record_CCA3';
const WORKFLOW_NAME = 'Delegate New > New SFDC Campaign member';
const ACTION_VARIANT = 'post_retry';
const DEFAULT_LOGIN_URL = 'https://login.salesforce.com';
const DEFAULT_API_VERSION = 'v62.0';
const SF_PROD_CONSUMER_KEY_SECRET = 'SF_CONSUMER_KEY_PROD';
const SF_PROD_USERNAME = 'hubspot.integration@nanoporetech.com';
const SF_PROD_JWT_PART_NAMES = ['SF_JWT_PART_01', 'SF_JWT_PART_02', 'SF_JWT_PART_03'];
const EXPOSED_OUTPUT_FIELDS = ['log', 'http', 'http_message', 'other', 'membership_id', 'operation'];

function safeStr(value) {
  return String(value == null ? '' : value).trim();
}

function norm(value) {
  return safeStr(value).toLowerCase();
}

function desiredStatusFromRegistrationStatus(value) {
  const normalized = norm(value);
  if (!normalized) return 'Registered';
  if (normalized === 'confirmed') return 'Registered';
  if (normalized === 'attended') return 'Attended';
  return '';
}

function jsonCompact(obj) {
  return JSON.stringify(obj == null ? {} : obj);
}

function selectOutputFields(outputs) {
  return EXPOSED_OUTPUT_FIELDS.reduce((acc, key) => {
    acc[key] = outputs[key];
    return acc;
  }, {});
}

function friendly(value) {
  const map = {
    200: 'OK',
    201: 'Created',
    204: 'No content',
    400: 'Bad Request – Your request is wrong',
    401: 'Unauthorized (credentials)',
    403: 'Forbidden (scope)',
    404: 'Not Found',
    405: 'Method Not Allowed',
    408: 'Request timeout',
    409: 'Conflict',
    422: 'Unprocessable entity',
    429: 'Too Many Requests',
    500: 'Internal Server Error',
    502: 'Bad gateway / processing limit met',
    503: 'Service temporarily unavailable',
    504: 'Gateway timeout / processing limit met',
  };
  if (typeof value === 'number') return map[value] || `HTTP ${value}`;
  const text = String(value || '');
  if (text === 'Timed_out') return 'Timeout';
  if (text === 'Request_error') return 'Request error';
  return 'No response';
}

function deriveHttpMessage(httpDict, overrides) {
  const out = {};
  Object.entries(httpDict || {}).forEach(([key, value]) => {
    const asNum = Number(value);
    out[key] = Number.isFinite(asNum) ? friendly(asNum) : friendly(value);
  });
  Object.entries(overrides || {}).forEach(([key, value]) => {
    if (value !== undefined && value !== null && String(value).trim() !== '') out[key] = String(value);
  });
  return out;
}

function envFirst(keys) {
  const list = Array.isArray(keys) ? keys : [keys];
  for (const key of list) {
    const raw = process.env[key];
    if (raw == null) continue;
    const value = String(raw).trim();
    if (value) return value;
  }
  return '';
}

function sfdcApiVersion() {
  const raw = envFirst(['salesforce_api_version', 'SFDC_API_VERSION', 'SALESFORCE_API_VERSION']) || DEFAULT_API_VERSION;
  const value = raw.replace(/^\//, '').trim();
  if (!value) return DEFAULT_API_VERSION;
  if (/^\d/.test(value)) return `v${value}`;
  return value;
}

function base64url(input) {
  const buf = Buffer.isBuffer(input) ? input : Buffer.from(String(input), 'utf8');
  return buf.toString('base64').replace(/=/g, '').replace(/\+/g, '-').replace(/\//g, '_');
}

function buildJwt({ iss, sub, aud, expiresInSec, keyObject }) {
  const now = Math.floor(Date.now() / 1000);
  const header = { alg: 'RS256', typ: 'JWT' };
  const payload = { iss, sub, aud, iat: now, exp: now + expiresInSec };
  const signingInput = `${base64url(jsonCompact(header))}.${base64url(jsonCompact(payload))}`;
  const signature = crypto.sign('RSA-SHA256', Buffer.from(signingInput, 'utf8'), keyObject);
  return `${signingInput}.${base64url(signature)}`;
}

function validateBase64String(b64) {
  if (!b64) return { ok: false, reason: 'empty' };
  if (!/^[A-Za-z0-9+/=]+$/.test(b64)) return { ok: false, reason: 'non_base64_chars' };
  if (b64.length % 4 !== 0) return { ok: false, reason: 'length_not_multiple_of_4' };
  return { ok: true };
}

function getPrivateKeyFromSecrets(httpStatuses) {
  const parts = SF_PROD_JWT_PART_NAMES.map((name) => envFirst(name));
  if (parts.some((part) => !part)) {
    httpStatuses.sfdc_key = 'NO_RESP';
    return {
      keyObject: null,
      meta: { key_scheme: 'SF_JWT_PART_prod_3parts', key_parts_expected: SF_PROD_JWT_PART_NAMES.length, key_parts_found: parts.filter(Boolean).length },
      error: 'Missing private key parts',
    };
  }
  const scheme = 'SF_JWT_PART_prod_3parts';

  const b64 = parts.map((item) => String(item).replace(/\s+/g, '')).join('');
  const valid = validateBase64String(b64);
  if (!valid.ok) {
    httpStatuses.sfdc_key = 'INVALID';
    return {
      keyObject: null,
      meta: { key_scheme: scheme, key_parts: parts.length, key_b64_len: b64.length, key_b64_reason: valid.reason },
      error: `Invalid base64 private key (${valid.reason})`,
    };
  }

  let pem = '';
  try {
    pem = Buffer.from(b64, 'base64').toString('utf8');
  } catch (err) {
    httpStatuses.sfdc_key = 'INVALID';
    return {
      keyObject: null,
      meta: { key_scheme: scheme, key_parts: parts.length, key_b64_len: b64.length },
      error: `Key decode failed: ${safeStr(err && err.message)}`,
    };
  }

  if (!pem.startsWith('-----BEGIN')) {
    httpStatuses.sfdc_key = 'INVALID';
    return {
      keyObject: null,
      meta: { key_scheme: scheme, key_parts: parts.length, pem_prefix: pem.slice(0, 20) },
      error: 'Decoded key is not PEM',
    };
  }

  try {
    const keyObject = crypto.createPrivateKey(pem);
    const fingerprint = crypto.createHash('sha256').update(pem).digest('hex').slice(0, 12);
    return {
      keyObject,
      meta: { key_scheme: scheme, key_parts: parts.length, key_b64_len: b64.length, pem_len: pem.length, key_fp: fingerprint },
      error: null,
    };
  } catch (err) {
    httpStatuses.sfdc_key = 'INVALID';
    return {
      keyObject: null,
      meta: { key_scheme: scheme, key_parts: parts.length, pem_len: pem.length },
      error: `PEM parse failed: ${safeStr(err && err.message)}`,
    };
  }
}

function sfdcErrorSummary(status, data, text) {
  if (Array.isArray(data)) {
    return data
      .filter((item) => item && typeof item === 'object')
      .map((item) => {
        const code = safeStr(item.errorCode);
        const msg = safeStr(item.message);
        if (code && msg) return `${code}: ${msg}`;
        return msg;
      })
      .filter(Boolean)
      .join('; ');
  }
  if (data && typeof data === 'object') {
    const err = safeStr(data.error);
    const desc = safeStr(data.error_description);
    if (err && desc) return `${err}: ${desc}`;
    if (safeStr(data.message)) return safeStr(data.message);
  }
  return safeStr(text) || `HTTP ${status}`;
}

async function httpRequest({ method, url, headers, params, body, timeoutMs }) {
  const target = new URL(url);
  Object.entries(params || {}).forEach(([key, value]) => target.searchParams.set(key, String(value)));

  if (typeof fetch === 'function') {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    try {
      const resp = await fetch(target.toString(), {
        method,
        headers: headers || {},
        body,
        signal: controller.signal,
      });
      const text = await resp.text();
      let json = null;
      try {
        json = text ? JSON.parse(text) : null;
      } catch (_err) {
        json = null;
      }
      return { status: resp.status, text, json };
    } finally {
      clearTimeout(timer);
    }
  }

  return new Promise((resolve, reject) => {
    const req = https.request(target, { method, headers: headers || {}, timeout: timeoutMs }, (res) => {
      const chunks = [];
      res.on('data', (chunk) => chunks.push(chunk));
      res.on('end', () => {
        const text = Buffer.concat(chunks).toString('utf8');
        let json = null;
        try {
          json = text ? JSON.parse(text) : null;
        } catch (_err) {
          json = null;
        }
        resolve({ status: res.statusCode || 0, text, json });
      });
    });
    req.on('timeout', () => req.destroy(new Error('timed_out')));
    req.on('error', reject);
    if (body) req.write(body);
    req.end();
  });
}

async function callOnce(name, method, url, options) {
  try {
    const payload =
      options.jsonBody != null ? Buffer.from(JSON.stringify(options.jsonBody), 'utf8') : options.dataBody != null ? Buffer.from(String(options.dataBody), 'utf8') : undefined;
    const resp = await httpRequest({
      method,
      url,
      headers: options.headers,
      params: options.params,
      body: payload,
      timeoutMs: options.timeoutMs,
    });
    options.http[name] = resp.status || 'NO_RESP';
    return { resp, err: null };
  } catch (err) {
    const message = safeStr(err && err.message);
    options.http[name] = message === 'timed_out' || message.toLowerCase().includes('abort') ? 'Timed_out' : 'Request_error';
    return { resp: null, err: message === 'timed_out' || message.toLowerCase().includes('abort') ? 'REQUEST -> Timeout' : `REQUEST -> ${message}` };
  }
}

function sfdcBase(instanceUrl, apiVersion) {
  return `${String(instanceUrl).replace(/\/+$/, '')}/services/data/${apiVersion}`;
}

function sfdcHeaders(accessToken) {
  return {
    Authorization: `Bearer ${accessToken}`,
    'Content-Type': 'application/json',
    Accept: 'application/json',
  };
}

async function sfdcQueryOne({ instanceUrl, apiVersion, accessToken, soql, httpStatuses, name, timeoutMs }) {
  const url = `${sfdcBase(instanceUrl, apiVersion)}/query`;
  const { resp, err } = await callOnce(name, 'GET', url, {
    http: httpStatuses,
    headers: sfdcHeaders(accessToken),
    params: { q: soql },
    timeoutMs,
  });
  if (err || !resp) return { record: null, err: err || 'No response' };
  if (resp.status !== 200) return { record: null, err: sfdcErrorSummary(resp.status, resp.json, resp.text) };
  const records = (resp.json && resp.json.records) || [];
  return { record: records.length ? records[0] : null, err: null };
}

async function getSalesforceAccessToken(httpStatuses) {
  const loginUrl =
    envFirst(['salesforce_login_url', 'SFDC_LOGIN_URL', 'SALESFORCE_LOGIN_URL', 'SF_LOGIN_AUD', 'SF_LOGIN_URL']) || DEFAULT_LOGIN_URL;
  const aud = String(loginUrl).replace(/\/+$/, '');
  const clientId = envFirst(SF_PROD_CONSUMER_KEY_SECRET);
  const username = SF_PROD_USERNAME;

  if (!clientId) {
    httpStatuses.sfdc_auth = 'NO_RESP';
    return { instanceUrl: null, accessToken: null, meta: { auth_method: 'jwt_bearer' }, err: `Missing ${SF_PROD_CONSUMER_KEY_SECRET}` };
  }

  const { keyObject, meta: keyMeta, error: keyErr } = getPrivateKeyFromSecrets(httpStatuses);
  if (keyErr || !keyObject) {
    httpStatuses.sfdc_auth = httpStatuses.sfdc_auth || 'NO_RESP';
    return { instanceUrl: null, accessToken: null, meta: { auth_method: 'jwt_bearer', ...keyMeta }, err: keyErr || 'Missing private key' };
  }

  const assertion = buildJwt({ iss: clientId, sub: username, aud, expiresInSec: 180, keyObject });
  const tokenUrl = `${aud}/services/oauth2/token`;
  const body = new URLSearchParams({
    grant_type: 'urn:ietf:params:oauth:grant-type:jwt-bearer',
    assertion,
  }).toString();

  const { resp, err } = await callOnce('sfdc_auth', 'POST', tokenUrl, {
    http: httpStatuses,
    headers: { 'Content-Type': 'application/x-www-form-urlencoded', Accept: 'application/json' },
    dataBody: body,
    timeoutMs: 5000,
  });
  if (err || !resp) return { instanceUrl: null, accessToken: null, meta: { auth_method: 'jwt_bearer', ...keyMeta }, err: err || 'No response' };
  if (resp.status !== 200) return { instanceUrl: null, accessToken: null, meta: { auth_method: 'jwt_bearer', ...keyMeta }, err: sfdcErrorSummary(resp.status, resp.json, resp.text) };

  const accessToken = safeStr(resp.json && resp.json.access_token);
  const instanceUrl = safeStr(resp.json && resp.json.instance_url);
  if (!accessToken || !instanceUrl) {
    return { instanceUrl: null, accessToken: null, meta: { auth_method: 'jwt_bearer', ...keyMeta }, err: 'Token response missing access_token/instance_url' };
  }
  return { instanceUrl, accessToken, meta: { auth_method: 'jwt_bearer', ...keyMeta }, err: null };
}

function blankOutputs() {
  return {
    membership_id: '',
    membership_status: '',
    operation: '',
    lock_error: 'false',
    error: '',
    error_message: '',
    error_state: '1',
    http: '{}',
    http_message: '{}',
    hs_delegate_id: '',
    level: 'INFO',
    log: '{}',
    other: '{}',
    salesforce_campaign_id: '',
    salesforce_campaign_member_status: '',
    salesforce_campaign_membership_id: '',
    salesforcecontactid: '',
    salesforceleadid: '',
    email: '',
    workflow_action: THIS_ACTION,
    workflow_name: WORKFLOW_NAME,
  };
}

function finalize(outputs, payload) {
  const httpMessage = payload.httpMessage || deriveHttpMessage(payload.httpStatuses, {});
  outputs.workflow_action = payload.actionName || THIS_ACTION;
  outputs.workflow_name = payload.workflowName || WORKFLOW_NAME;
  outputs.level = payload.level;
  outputs.error_state = String(payload.errorState);
  outputs.error_message = safeStr(payload.errorMessage || '');
  outputs.http = jsonCompact(payload.httpStatuses);
  outputs.http_message = jsonCompact(httpMessage);
  outputs.other = jsonCompact(payload.otherPayload || {});

  const logPayload = {
    workflow_action: outputs.workflow_action,
    level: outputs.level,
    error_state: outputs.error_state,
    workflow_name: outputs.workflow_name,
    hs_delegate_id: outputs.hs_delegate_id,
    salesforce_campaign_id: outputs.salesforce_campaign_id,
    salesforce_campaign_membership_id: outputs.salesforce_campaign_membership_id,
    membership_id: outputs.membership_id,
    membership_status: outputs.membership_status,
    salesforce_campaign_member_status: outputs.salesforce_campaign_member_status,
    salesforcecontactid: outputs.salesforcecontactid,
    salesforceleadid: outputs.salesforceleadid,
    email: outputs.email,
    error: { http: payload.httpStatuses, http_message: httpMessage },
    operation: outputs.operation || safeStr(payload.otherPayload && payload.otherPayload.operation),
    action_variant: ACTION_VARIANT,
  };
  if (payload.otherPayload && Object.prototype.hasOwnProperty.call(payload.otherPayload, 'lock_error')) {
    logPayload.lock_error = payload.otherPayload.lock_error;
  }
  outputs.log = jsonCompact(logPayload);
  return { outputFields: selectOutputFields(outputs) };
}

function isLockError(message) {
  return String(message || '').includes('UNABLE_TO_LOCK_ROW');
}

async function core(event) {
  const inputs = (event && event.inputFields) || {};
  const hsDelegateId = safeStr(inputs.hs_delegate_id);
  const campaignId = safeStr(inputs.salesforce_campaign_id);
  const registrationStatus = norm(inputs.registration_status);
  const desiredStatus = desiredStatusFromRegistrationStatus(registrationStatus);
  const membershipIdIn = safeStr(inputs.salesforce_campaign_membership_id);
  const salesforcecontactid = safeStr(inputs.salesforcecontactid);
  const salesforceleadid = safeStr(inputs.salesforceleadid);
  const email = safeStr(inputs.email);

  const outputs = blankOutputs();
  outputs.hs_delegate_id = hsDelegateId;
  outputs.salesforce_campaign_id = campaignId;
  outputs.salesforce_campaign_member_status = desiredStatus;
  outputs.salesforce_campaign_membership_id = membershipIdIn;
  outputs.salesforcecontactid = salesforcecontactid;
  outputs.salesforceleadid = salesforceleadid;
  outputs.email = email;

  const httpStatuses = {};
  const otherPayload = {
    operation: 'failed',
    action_variant: ACTION_VARIANT,
    auth_method: '',
    api_version: sfdcApiVersion(),
    registration_status: registrationStatus,
    desired_status: desiredStatus,
  };

  const finish = (payload) => finalize(outputs, { ...payload, otherPayload });

  if (!hsDelegateId) httpStatuses.input_hs_delegate_id = 'NO_RESP';
  if (!campaignId) httpStatuses.input_salesforce_campaign_id = 'NO_RESP';
  if (!desiredStatus) {
    httpStatuses.input_registration_status = 'INVALID';
  }
  if (salesforcecontactid && salesforceleadid) httpStatuses.input_salesforce_ids = 'INVALID';
  if (!salesforcecontactid && !salesforceleadid) httpStatuses.input_salesforce_ids = 'NO_RESP';
  if (Object.keys(httpStatuses).length) {
    return finish({
      actionName: THIS_ACTION,
      level: 'ERROR',
      errorState: 1,
      httpStatuses,
      httpMessage: deriveHttpMessage(httpStatuses, {
        input_registration_status: "registration_status must be blank, 'confirmed', or 'attended'",
        input_salesforce_ids: 'Provide exactly one of salesforcecontactid or salesforceleadid',
      }),
      errorMessage: 'Missing or invalid inputs',
    });
  }

  const personField = salesforcecontactid ? 'ContactId' : 'LeadId';
  const personId = salesforcecontactid || salesforceleadid;
  otherPayload.person_field = personField;
  otherPayload.person_id = personId;

  const { instanceUrl, accessToken, meta, err: authErr } = await getSalesforceAccessToken(httpStatuses);
  Object.assign(otherPayload, meta || {});
  otherPayload.auth_method = (meta && meta.auth_method) || '';
  if (authErr || !instanceUrl || !accessToken) {
    return finish({
      actionName: THIS_ACTION,
      level: 'ERROR',
      errorState: 1,
      httpStatuses,
      httpMessage: deriveHttpMessage(httpStatuses, { sfdc_auth: authErr || 'Missing Salesforce auth' }),
      errorMessage: 'Salesforce authentication failed',
    });
  }

  const apiVersion = otherPayload.api_version;
  const existing = await sfdcQueryOne({
    instanceUrl,
    apiVersion,
    accessToken,
    soql: `SELECT Id, Status, CampaignId, ContactId, LeadId FROM CampaignMember WHERE CampaignId = '${campaignId}' AND ${personField} = '${personId}' LIMIT 1`,
    httpStatuses,
    name: 'sfdc_query_existing',
    timeoutMs: 4000,
  });
  if (existing.err) {
    return finish({
      actionName: THIS_ACTION,
      level: 'ERROR',
      errorState: 1,
      httpStatuses,
      httpMessage: deriveHttpMessage(httpStatuses, { sfdc_query_existing: existing.err }),
      errorMessage: 'Unable to query CampaignMember',
    });
  }

  if (existing.record) {
    outputs.membership_id = safeStr(existing.record.Id);
    outputs.membership_status = safeStr(existing.record.Status);
    otherPayload.current_status = outputs.membership_status;
    if (norm(outputs.membership_status) === norm(desiredStatus)) {
      outputs.operation = 'skipped';
      otherPayload.operation = 'skipped';
      return finish({ actionName: THIS_ACTION, level: 'INFO', errorState: 0, httpStatuses });
    }
    outputs.operation = 'found_needs_patch';
    otherPayload.operation = 'found_needs_patch';
    otherPayload.needs_patch = true;
    return finish({ actionName: THIS_ACTION, level: 'INFO', errorState: 0, httpStatuses });
  }

  const createResp = await callOnce('sfdc_create_campaign_member', 'POST', `${sfdcBase(instanceUrl, apiVersion)}/sobjects/CampaignMember`, {
    http: httpStatuses,
    headers: sfdcHeaders(accessToken),
    jsonBody: { CampaignId: campaignId, [personField]: personId, Status: desiredStatus },
    timeoutMs: 5000,
  });
  if (createResp.err || !createResp.resp || ![200, 201, 204].includes(createResp.resp.status)) {
    const override =
      createResp.err ||
      sfdcErrorSummary(createResp.resp ? createResp.resp.status : 0, createResp.resp ? createResp.resp.json : null, createResp.resp ? createResp.resp.text : '');
    if (isLockError(override)) {
      outputs.lock_error = 'true';
      outputs.operation = 'lock_error';
      otherPayload.lock_error = true;
      otherPayload.operation = 'lock_error';
      return finish({
        actionName: THIS_ACTION,
        level: 'WARN',
        errorState: 1,
        httpStatuses,
        httpMessage: deriveHttpMessage(httpStatuses, { sfdc_create_campaign_member: override }),
        errorMessage: 'Salesforce POST retry failed with lock error',
      });
    }
    return finish({
      actionName: THIS_ACTION,
      level: 'ERROR',
      errorState: 1,
      httpStatuses,
      httpMessage: deriveHttpMessage(httpStatuses, { sfdc_create_campaign_member: override }),
      errorMessage: 'Salesforce POST retry failed',
    });
  }

  outputs.membership_id = safeStr(createResp.resp.json && createResp.resp.json.id);
  if (!outputs.membership_id) {
    const fallback = await sfdcQueryOne({
      instanceUrl,
      apiVersion,
      accessToken,
      soql: `SELECT Id FROM CampaignMember WHERE CampaignId = '${campaignId}' AND ${personField} = '${personId}' LIMIT 1`,
      httpStatuses,
      name: 'sfdc_query_post_create',
      timeoutMs: 4000,
    });
    outputs.membership_id = safeStr(fallback.record && fallback.record.Id);
  }
  if (!outputs.membership_id) {
    return finish({
      actionName: THIS_ACTION,
      level: 'ERROR',
      errorState: 1,
      httpStatuses,
      httpMessage: deriveHttpMessage(httpStatuses, { sfdc_create_campaign_member: 'Created but could not locate id' }),
      errorMessage: 'CampaignMember created but id not found',
    });
  }

  const verified = await sfdcQueryOne({
    instanceUrl,
    apiVersion,
    accessToken,
    soql: `SELECT Id, Status FROM CampaignMember WHERE Id = '${outputs.membership_id}' LIMIT 1`,
    httpStatuses,
    name: 'sfdc_query_verify',
    timeoutMs: 4000,
  });
  if (verified.err || !verified.record) {
    return finish({
      actionName: THIS_ACTION,
      level: 'ERROR',
      errorState: 1,
      httpStatuses,
      httpMessage: deriveHttpMessage(httpStatuses, { sfdc_query_verify: verified.err || 'No CampaignMember record' }),
      errorMessage: 'Unable to verify CampaignMember after POST retry',
    });
  }

  outputs.membership_status = safeStr(verified.record.Status);
  outputs.operation = 'created';
  otherPayload.operation = 'created';
  otherPayload.verified_status = outputs.membership_status;
  if (norm(outputs.membership_status) !== norm(desiredStatus)) {
    httpStatuses.sfdc_verify_status = 'INVALID';
    return finish({
      actionName: THIS_ACTION,
      level: 'ERROR',
      errorState: 1,
      httpStatuses,
      httpMessage: deriveHttpMessage(httpStatuses, {
        sfdc_verify_status: `Status mismatch (wanted='${desiredStatus}', got='${outputs.membership_status}')`,
      }),
      errorMessage: 'CampaignMember status did not persist (likely invalid status for campaign)',
    });
  }

  return finish({ actionName: THIS_ACTION, level: 'INFO', errorState: 0, httpStatuses });
}

exports.main = async (event, callback) => {
  try {
    callback(await core(event || {}));
  } catch (err) {
    const outputs = blankOutputs();
    const httpStatuses = { uncaught_exception: 'Request_error' };
    callback(
      finalize(outputs, {
        actionName: THIS_ACTION,
        level: 'ERROR',
        errorState: 1,
        httpStatuses,
        httpMessage: deriveHttpMessage(httpStatuses, { uncaught_exception: safeStr(err && err.message ? err.message : err) }),
        otherPayload: { operation: 'failed', action_variant: ACTION_VARIANT },
        errorMessage: 'Unhandled exception in new_delegate_record_CCA3',
      })
    );
  }
};

exports._internal = {
  core,
  getPrivateKeyFromSecrets,
  getSalesforceAccessToken,
  blankOutputs,
  finalize,
};

/*
 * Masks delegate workflow fields and ships a Grafana Loki log line for the preceding action result.
 * Branch before: Run after the preceding workflow action emits loggable fields for this delegate record path.
 * Branch after: Branch only on logger result: dry run, logged successfully, or logging error.
 * Expected inputs: upstream workflow fields via event.inputFields limited to log, http, http_message, and other.
 * Expected outputs: logged, simulated, payload (dry run only), logging_http_status, error.
 */
const https = require('https');
const { URL } = require('url');

const DEFAULT_ACTION = 'new_delegate_record_CCA3';
const WORKFLOW_NAME = 'Delegate New > New SFDC Campaign member';
const GRAFANA_ENV = 'prod';
const JOB_NAME = 'swoogo_sfdc_campaign';
const LOKI_ENDPOINT = (process.env.LOKI_URL || process.env.grafana_url || 'https://logs-prod-012.grafana.net/loki/api/v1/push').trim();
const EMAIL_RE = /([A-Za-z0-9._%+-]+)@([A-Za-z0-9.-]+\.[A-Za-z]{2,})/g;

function safeJsonParse(value, fallback) {
  if (!value) return fallback;
  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      return parsed && typeof parsed === 'object' ? parsed : fallback;
    } catch (_err) {
      return fallback;
    }
  }
  return typeof value === 'object' ? value : fallback;
}

function maskLocal(local) {
  const value = String(local || '');
  const first = value.charAt(0) || 'a';
  const last = value.charAt(value.length - 1) || first;
  return `${first}***${last}`;
}

function maskEmailString(value) {
  return String(value || '').replace(EMAIL_RE, (_match, local, domain) => `${maskLocal(local)}@${domain}`);
}

function maskDeep(value) {
  if (Array.isArray(value)) return value.map((item) => maskDeep(item));
  if (value && typeof value === 'object') {
    return Object.keys(value).reduce((acc, key) => {
      acc[key] = maskDeep(value[key]);
      return acc;
    }, {});
  }
  if (typeof value === 'string') return maskEmailString(value);
  return value;
}

function buildLogLine(inputs) {
  const parsedLog = safeJsonParse(inputs.log, {});
  const payload = {
    workflow_action: parsedLog.workflow_action || inputs.workflow_action || DEFAULT_ACTION,
    workflow_name: parsedLog.workflow_name || inputs.workflow_name || WORKFLOW_NAME,
    level: parsedLog.level || inputs.level || 'INFO',
    error_state: parsedLog.error_state || inputs.error_state || '0',
    hs_delegate_id: parsedLog.hs_delegate_id || inputs.hs_delegate_id || '',
    salesforce_campaign_id: parsedLog.salesforce_campaign_id || inputs.salesforce_campaign_id || '',
    salesforce_campaign_membership_id:
      parsedLog.salesforce_campaign_membership_id || inputs.salesforce_campaign_membership_id || '',
    membership_id: parsedLog.membership_id || inputs.membership_id || '',
    membership_status: parsedLog.membership_status || inputs.membership_status || '',
    salesforce_campaign_member_status:
      parsedLog.salesforce_campaign_member_status || inputs.salesforce_campaign_member_status || '',
    salesforcecontactid: parsedLog.salesforcecontactid || inputs.salesforcecontactid || '',
    salesforceleadid: parsedLog.salesforceleadid || inputs.salesforceleadid || '',
    email: parsedLog.email || inputs.email || '',
    error: {
      http: (parsedLog.error && parsedLog.error.http) || safeJsonParse(inputs.http, {}),
      http_message: (parsedLog.error && parsedLog.error.http_message) || safeJsonParse(inputs.http_message, {}),
    },
    other: safeJsonParse(inputs.other, parsedLog.other || {}),
  };
  payload.campaign_member_id = payload.membership_id || payload.salesforce_campaign_membership_id || '';
  if (parsedLog.operation || payload.other.operation) payload.operation = parsedLog.operation || payload.other.operation;
  if (parsedLog.action_variant || payload.other.action_variant) payload.action_variant = parsedLog.action_variant || payload.other.action_variant;
  if (payload.other.lock_error !== undefined) payload.lock_error = payload.other.lock_error;
  return JSON.stringify(maskDeep(payload));
}

async function postJson(url, payload, user, token) {
  const target = new URL(url);
  const body = JSON.stringify(payload);
  const auth = `Basic ${Buffer.from(`${user}:${token}`).toString('base64')}`;

  if (typeof fetch === 'function') {
    const resp = await fetch(target.toString(), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: auth },
      body,
    });
    const text = await resp.text();
    if (resp.status < 200 || resp.status >= 300) throw new Error(text || `HTTP ${resp.status}`);
    return { status: resp.status };
  }

  return new Promise((resolve, reject) => {
    const req = https.request(
      target,
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(body),
          Authorization: auth,
        },
      },
      (res) => {
        const chunks = [];
        res.on('data', (chunk) => chunks.push(chunk));
        res.on('end', () => {
          const text = Buffer.concat(chunks).toString('utf8');
          if ((res.statusCode || 0) < 200 || (res.statusCode || 0) >= 300) {
            reject(new Error(text || `HTTP ${res.statusCode || 0}`));
            return;
          }
          resolve({ status: res.statusCode || 0 });
        });
      }
    );
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

exports.main = async (event, callback) => {
  try {
    const user = (process.env.grafana_user || process.env.GRAFANA_USER || '').trim();
    const token = (process.env.grafana_token || process.env.GRAFANA_TOKEN || '').trim();
    if (!user || !token) throw new Error('Missing grafana_user or grafana_token environment variables.');

    const payload = {
      streams: [
        {
          stream: {
            service_name: 'hubspot',
            environment: GRAFANA_ENV,
            process: 'workflow',
            team: 'marketing_technology',
            job: JOB_NAME,
          },
          values: [[`${Date.now()}000000`, buildLogLine((event && event.inputFields) || {})]],
        },
      ],
    };

    if (String(process.env.GRAFANA_DRY_RUN || '').trim() === '1') {
      callback({ outputFields: { logged: false, simulated: true, payload } });
      return;
    }

    const res = await postJson(LOKI_ENDPOINT, payload, user, token);
    callback({ outputFields: { logged: true, simulated: false, logging_http_status: res.status } });
  } catch (error) {
    callback({
      outputFields: {
        logged: false,
        error: String(error && error.message ? error.message : error),
      },
    });
  }
};

/*
 * Retries Salesforce CampaignMember status patching after a failed patch, then returns verified membership details for the delegate workflow.
 * Branch before: Run only when a CampaignMember already exists and needs a status patch, or when retrying a failed patch.
 * Branch after: Route by output state: skipped, patched, lock_error, or error.
 * Expected inputs: hs_delegate_id, salesforce_campaign_membership_id, registration_status, optional salesforce_campaign_id, salesforcecontactid, salesforceleadid, email.
 * Expected outputs: log, http, http_message, other.
 */
const crypto = require('crypto');
const https = require('https');
const { URL } = require('url');

const THIS_ACTION = 'new_delegate_record_CCA4';
const WORKFLOW_NAME = 'Delegate New > New SFDC Campaign member';
const ACTION_VARIANT = 'patch_retry';
const DEFAULT_LOGIN_URL = 'https://login.salesforce.com';
const DEFAULT_API_VERSION = 'v62.0';
const SF_PROD_CONSUMER_KEY_SECRET = 'SF_CONSUMER_KEY_PROD';
const SF_PROD_USERNAME = 'hubspot.integration@nanoporetech.com';
const SF_PROD_JWT_PART_NAMES = ['SF_JWT_PART_01', 'SF_JWT_PART_02', 'SF_JWT_PART_03'];
const EXPOSED_OUTPUT_FIELDS = ['log', 'http', 'http_message', 'other'];

function safeStr(value) {
  return String(value == null ? '' : value).trim();
}

function norm(value) {
  return safeStr(value).toLowerCase();
}

function desiredStatusFromRegistrationStatus(value) {
  const normalized = norm(value);
  if (!normalized) return 'Registered';
  if (normalized === 'confirmed') return 'Registered';
  if (normalized === 'attended') return 'Attended';
  return '';
}

function jsonCompact(obj) {
  return JSON.stringify(obj == null ? {} : obj);
}

function selectOutputFields(outputs) {
  return EXPOSED_OUTPUT_FIELDS.reduce((acc, key) => {
    acc[key] = outputs[key];
    return acc;
  }, {});
}

function friendly(value) {
  const map = {
    200: 'OK',
    201: 'Created',
    204: 'No content',
    400: 'Bad Request – Your request is wrong',
    401: 'Unauthorized (credentials)',
    403: 'Forbidden (scope)',
    404: 'Not Found',
    405: 'Method Not Allowed',
    408: 'Request timeout',
    409: 'Conflict',
    422: 'Unprocessable entity',
    429: 'Too Many Requests',
    500: 'Internal Server Error',
    502: 'Bad gateway / processing limit met',
    503: 'Service temporarily unavailable',
    504: 'Gateway timeout / processing limit met',
  };
  if (typeof value === 'number') return map[value] || `HTTP ${value}`;
  const text = String(value || '');
  if (text === 'Timed_out') return 'Timeout';
  if (text === 'Request_error') return 'Request error';
  return 'No response';
}

function deriveHttpMessage(httpDict, overrides) {
  const out = {};
  Object.entries(httpDict || {}).forEach(([key, value]) => {
    const asNum = Number(value);
    out[key] = Number.isFinite(asNum) ? friendly(asNum) : friendly(value);
  });
  Object.entries(overrides || {}).forEach(([key, value]) => {
    if (value !== undefined && value !== null && String(value).trim() !== '') out[key] = String(value);
  });
  return out;
}

function envFirst(keys) {
  const list = Array.isArray(keys) ? keys : [keys];
  for (const key of list) {
    const raw = process.env[key];
    if (raw == null) continue;
    const value = String(raw).trim();
    if (value) return value;
  }
  return '';
}

function sfdcApiVersion() {
  const raw = envFirst(['salesforce_api_version', 'SFDC_API_VERSION', 'SALESFORCE_API_VERSION']) || DEFAULT_API_VERSION;
  const value = raw.replace(/^\//, '').trim();
  if (!value) return DEFAULT_API_VERSION;
  if (/^\d/.test(value)) return `v${value}`;
  return value;
}

function base64url(input) {
  const buf = Buffer.isBuffer(input) ? input : Buffer.from(String(input), 'utf8');
  return buf.toString('base64').replace(/=/g, '').replace(/\+/g, '-').replace(/\//g, '_');
}

function buildJwt({ iss, sub, aud, expiresInSec, keyObject }) {
  const now = Math.floor(Date.now() / 1000);
  const header = { alg: 'RS256', typ: 'JWT' };
  const payload = { iss, sub, aud, iat: now, exp: now + expiresInSec };
  const signingInput = `${base64url(jsonCompact(header))}.${base64url(jsonCompact(payload))}`;
  const signature = crypto.sign('RSA-SHA256', Buffer.from(signingInput, 'utf8'), keyObject);
  return `${signingInput}.${base64url(signature)}`;
}

function validateBase64String(b64) {
  if (!b64) return { ok: false, reason: 'empty' };
  if (!/^[A-Za-z0-9+/=]+$/.test(b64)) return { ok: false, reason: 'non_base64_chars' };
  if (b64.length % 4 !== 0) return { ok: false, reason: 'length_not_multiple_of_4' };
  return { ok: true };
}

function getPrivateKeyFromSecrets(httpStatuses) {
  const parts = SF_PROD_JWT_PART_NAMES.map((name) => envFirst(name));
  if (parts.some((part) => !part)) {
    httpStatuses.sfdc_key = 'NO_RESP';
    return {
      keyObject: null,
      meta: { key_scheme: 'SF_JWT_PART_prod_3parts', key_parts_expected: SF_PROD_JWT_PART_NAMES.length, key_parts_found: parts.filter(Boolean).length },
      error: 'Missing private key parts',
    };
  }
  const scheme = 'SF_JWT_PART_prod_3parts';

  const b64 = parts.map((item) => String(item).replace(/\s+/g, '')).join('');
  const valid = validateBase64String(b64);
  if (!valid.ok) {
    httpStatuses.sfdc_key = 'INVALID';
    return {
      keyObject: null,
      meta: { key_scheme: scheme, key_parts: parts.length, key_b64_len: b64.length, key_b64_reason: valid.reason },
      error: `Invalid base64 private key (${valid.reason})`,
    };
  }

  let pem = '';
  try {
    pem = Buffer.from(b64, 'base64').toString('utf8');
  } catch (err) {
    httpStatuses.sfdc_key = 'INVALID';
    return {
      keyObject: null,
      meta: { key_scheme: scheme, key_parts: parts.length, key_b64_len: b64.length },
      error: `Key decode failed: ${safeStr(err && err.message)}`,
    };
  }

  if (!pem.startsWith('-----BEGIN')) {
    httpStatuses.sfdc_key = 'INVALID';
    return {
      keyObject: null,
      meta: { key_scheme: scheme, key_parts: parts.length, pem_prefix: pem.slice(0, 20) },
      error: 'Decoded key is not PEM',
    };
  }

  try {
    const keyObject = crypto.createPrivateKey(pem);
    const fingerprint = crypto.createHash('sha256').update(pem).digest('hex').slice(0, 12);
    return {
      keyObject,
      meta: { key_scheme: scheme, key_parts: parts.length, key_b64_len: b64.length, pem_len: pem.length, key_fp: fingerprint },
      error: null,
    };
  } catch (err) {
    httpStatuses.sfdc_key = 'INVALID';
    return {
      keyObject: null,
      meta: { key_scheme: scheme, key_parts: parts.length, pem_len: pem.length },
      error: `PEM parse failed: ${safeStr(err && err.message)}`,
    };
  }
}

function sfdcErrorSummary(status, data, text) {
  if (Array.isArray(data)) {
    return data
      .filter((item) => item && typeof item === 'object')
      .map((item) => {
        const code = safeStr(item.errorCode);
        const msg = safeStr(item.message);
        if (code && msg) return `${code}: ${msg}`;
        return msg;
      })
      .filter(Boolean)
      .join('; ');
  }
  if (data && typeof data === 'object') {
    const err = safeStr(data.error);
    const desc = safeStr(data.error_description);
    if (err && desc) return `${err}: ${desc}`;
    if (safeStr(data.message)) return safeStr(data.message);
  }
  return safeStr(text) || `HTTP ${status}`;
}

async function httpRequest({ method, url, headers, params, body, timeoutMs }) {
  const target = new URL(url);
  Object.entries(params || {}).forEach(([key, value]) => target.searchParams.set(key, String(value)));

  if (typeof fetch === 'function') {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    try {
      const resp = await fetch(target.toString(), {
        method,
        headers: headers || {},
        body,
        signal: controller.signal,
      });
      const text = await resp.text();
      let json = null;
      try {
        json = text ? JSON.parse(text) : null;
      } catch (_err) {
        json = null;
      }
      return { status: resp.status, text, json };
    } finally {
      clearTimeout(timer);
    }
  }

  return new Promise((resolve, reject) => {
    const req = https.request(target, { method, headers: headers || {}, timeout: timeoutMs }, (res) => {
      const chunks = [];
      res.on('data', (chunk) => chunks.push(chunk));
      res.on('end', () => {
        const text = Buffer.concat(chunks).toString('utf8');
        let json = null;
        try {
          json = text ? JSON.parse(text) : null;
        } catch (_err) {
          json = null;
        }
        resolve({ status: res.statusCode || 0, text, json });
      });
    });
    req.on('timeout', () => req.destroy(new Error('timed_out')));
    req.on('error', reject);
    if (body) req.write(body);
    req.end();
  });
}

async function callOnce(name, method, url, options) {
  try {
    const payload =
      options.jsonBody != null ? Buffer.from(JSON.stringify(options.jsonBody), 'utf8') : options.dataBody != null ? Buffer.from(String(options.dataBody), 'utf8') : undefined;
    const resp = await httpRequest({
      method,
      url,
      headers: options.headers,
      params: options.params,
      body: payload,
      timeoutMs: options.timeoutMs,
    });
    options.http[name] = resp.status || 'NO_RESP';
    return { resp, err: null };
  } catch (err) {
    const message = safeStr(err && err.message);
    options.http[name] = message === 'timed_out' || message.toLowerCase().includes('abort') ? 'Timed_out' : 'Request_error';
    return { resp: null, err: message === 'timed_out' || message.toLowerCase().includes('abort') ? 'REQUEST -> Timeout' : `REQUEST -> ${message}` };
  }
}

function sfdcBase(instanceUrl, apiVersion) {
  return `${String(instanceUrl).replace(/\/+$/, '')}/services/data/${apiVersion}`;
}

function sfdcHeaders(accessToken) {
  return {
    Authorization: `Bearer ${accessToken}`,
    'Content-Type': 'application/json',
    Accept: 'application/json',
  };
}

async function sfdcQueryOne({ instanceUrl, apiVersion, accessToken, soql, httpStatuses, name, timeoutMs }) {
  const url = `${sfdcBase(instanceUrl, apiVersion)}/query`;
  const { resp, err } = await callOnce(name, 'GET', url, {
    http: httpStatuses,
    headers: sfdcHeaders(accessToken),
    params: { q: soql },
    timeoutMs,
  });
  if (err || !resp) return { record: null, err: err || 'No response' };
  if (resp.status !== 200) return { record: null, err: sfdcErrorSummary(resp.status, resp.json, resp.text) };
  const records = (resp.json && resp.json.records) || [];
  return { record: records.length ? records[0] : null, err: null };
}

async function getSalesforceAccessToken(httpStatuses) {
  const loginUrl =
    envFirst(['salesforce_login_url', 'SFDC_LOGIN_URL', 'SALESFORCE_LOGIN_URL', 'SF_LOGIN_AUD', 'SF_LOGIN_URL']) || DEFAULT_LOGIN_URL;
  const aud = String(loginUrl).replace(/\/+$/, '');
  const clientId = envFirst(SF_PROD_CONSUMER_KEY_SECRET);
  const username = SF_PROD_USERNAME;

  if (!clientId) {
    httpStatuses.sfdc_auth = 'NO_RESP';
    return { instanceUrl: null, accessToken: null, meta: { auth_method: 'jwt_bearer' }, err: `Missing ${SF_PROD_CONSUMER_KEY_SECRET}` };
  }

  const { keyObject, meta: keyMeta, error: keyErr } = getPrivateKeyFromSecrets(httpStatuses);
  if (keyErr || !keyObject) {
    httpStatuses.sfdc_auth = httpStatuses.sfdc_auth || 'NO_RESP';
    return { instanceUrl: null, accessToken: null, meta: { auth_method: 'jwt_bearer', ...keyMeta }, err: keyErr || 'Missing private key' };
  }

  const assertion = buildJwt({ iss: clientId, sub: username, aud, expiresInSec: 180, keyObject });
  const tokenUrl = `${aud}/services/oauth2/token`;
  const body = new URLSearchParams({
    grant_type: 'urn:ietf:params:oauth:grant-type:jwt-bearer',
    assertion,
  }).toString();

  const { resp, err } = await callOnce('sfdc_auth', 'POST', tokenUrl, {
    http: httpStatuses,
    headers: { 'Content-Type': 'application/x-www-form-urlencoded', Accept: 'application/json' },
    dataBody: body,
    timeoutMs: 5000,
  });
  if (err || !resp) return { instanceUrl: null, accessToken: null, meta: { auth_method: 'jwt_bearer', ...keyMeta }, err: err || 'No response' };
  if (resp.status !== 200) return { instanceUrl: null, accessToken: null, meta: { auth_method: 'jwt_bearer', ...keyMeta }, err: sfdcErrorSummary(resp.status, resp.json, resp.text) };

  const accessToken = safeStr(resp.json && resp.json.access_token);
  const instanceUrl = safeStr(resp.json && resp.json.instance_url);
  if (!accessToken || !instanceUrl) {
    return { instanceUrl: null, accessToken: null, meta: { auth_method: 'jwt_bearer', ...keyMeta }, err: 'Token response missing access_token/instance_url' };
  }
  return { instanceUrl, accessToken, meta: { auth_method: 'jwt_bearer', ...keyMeta }, err: null };
}

function blankOutputs() {
  return {
    membership_id: '',
    membership_status: '',
    operation: '',
    lock_error: 'false',
    error: '',
    error_message: '',
    error_state: '1',
    http: '{}',
    http_message: '{}',
    hs_delegate_id: '',
    level: 'INFO',
    log: '{}',
    other: '{}',
    salesforce_campaign_id: '',
    salesforce_campaign_member_status: '',
    salesforce_campaign_membership_id: '',
    salesforcecontactid: '',
    salesforceleadid: '',
    email: '',
    workflow_action: THIS_ACTION,
    workflow_name: WORKFLOW_NAME,
  };
}

function finalize(outputs, payload) {
  const httpMessage = payload.httpMessage || deriveHttpMessage(payload.httpStatuses, {});
  outputs.workflow_action = payload.actionName || THIS_ACTION;
  outputs.workflow_name = payload.workflowName || WORKFLOW_NAME;
  outputs.level = payload.level;
  outputs.error_state = String(payload.errorState);
  outputs.error_message = safeStr(payload.errorMessage || '');
  outputs.http = jsonCompact(payload.httpStatuses);
  outputs.http_message = jsonCompact(httpMessage);
  outputs.other = jsonCompact(payload.otherPayload || {});

  const logPayload = {
    workflow_action: outputs.workflow_action,
    level: outputs.level,
    error_state: outputs.error_state,
    workflow_name: outputs.workflow_name,
    hs_delegate_id: outputs.hs_delegate_id,
    salesforce_campaign_id: outputs.salesforce_campaign_id,
    salesforce_campaign_membership_id: outputs.salesforce_campaign_membership_id,
    membership_id: outputs.membership_id,
    membership_status: outputs.membership_status,
    salesforce_campaign_member_status: outputs.salesforce_campaign_member_status,
    salesforcecontactid: outputs.salesforcecontactid,
    salesforceleadid: outputs.salesforceleadid,
    email: outputs.email,
    error: { http: payload.httpStatuses, http_message: httpMessage },
    operation: outputs.operation || safeStr(payload.otherPayload && payload.otherPayload.operation),
    action_variant: ACTION_VARIANT,
  };
  if (payload.otherPayload && Object.prototype.hasOwnProperty.call(payload.otherPayload, 'lock_error')) {
    logPayload.lock_error = payload.otherPayload.lock_error;
  }
  outputs.log = jsonCompact(logPayload);
  return { outputFields: selectOutputFields(outputs) };
}

function isLockError(message) {
  return String(message || '').includes('UNABLE_TO_LOCK_ROW');
}

async function core(event) {
  const inputs = (event && event.inputFields) || {};
  const hsDelegateId = safeStr(inputs.hs_delegate_id);
  const campaignId = safeStr(inputs.salesforce_campaign_id);
  const registrationStatus = norm(inputs.registration_status);
  const desiredStatus = desiredStatusFromRegistrationStatus(registrationStatus);
  const membershipIdIn = safeStr(inputs.salesforce_campaign_membership_id);
  const salesforcecontactid = safeStr(inputs.salesforcecontactid);
  const salesforceleadid = safeStr(inputs.salesforceleadid);
  const email = safeStr(inputs.email);

  const outputs = blankOutputs();
  outputs.hs_delegate_id = hsDelegateId;
  outputs.salesforce_campaign_id = campaignId;
  outputs.salesforce_campaign_member_status = desiredStatus;
  outputs.salesforce_campaign_membership_id = membershipIdIn;
  outputs.salesforcecontactid = salesforcecontactid;
  outputs.salesforceleadid = salesforceleadid;
  outputs.email = email;

  const httpStatuses = {};
  const otherPayload = {
    operation: 'failed',
    action_variant: ACTION_VARIANT,
    auth_method: '',
    api_version: sfdcApiVersion(),
    registration_status: registrationStatus,
    desired_status: desiredStatus,
  };

  const finish = (payload) => finalize(outputs, { ...payload, otherPayload });

  if (!hsDelegateId) httpStatuses.input_hs_delegate_id = 'NO_RESP';
  if (!desiredStatus) {
    httpStatuses.input_registration_status = 'INVALID';
  }
  if (!membershipIdIn) httpStatuses.input_salesforce_campaign_membership_id = 'NO_RESP';
  if (Object.keys(httpStatuses).length) {
    return finish({
      actionName: THIS_ACTION,
      level: 'ERROR',
      errorState: 1,
      httpStatuses,
      httpMessage: deriveHttpMessage(httpStatuses, {
        input_registration_status: "registration_status must be blank, 'confirmed', or 'attended'",
      }),
      errorMessage: 'Missing or invalid inputs',
    });
  }

  const { instanceUrl, accessToken, meta, err: authErr } = await getSalesforceAccessToken(httpStatuses);
  Object.assign(otherPayload, meta || {});
  otherPayload.auth_method = (meta && meta.auth_method) || '';
  if (authErr || !instanceUrl || !accessToken) {
    return finish({
      actionName: THIS_ACTION,
      level: 'ERROR',
      errorState: 1,
      httpStatuses,
      httpMessage: deriveHttpMessage(httpStatuses, { sfdc_auth: authErr || 'Missing Salesforce auth' }),
      errorMessage: 'Salesforce authentication failed',
    });
  }

  const apiVersion = otherPayload.api_version;
  outputs.membership_id = membershipIdIn;
  const verified = await sfdcQueryOne({
    instanceUrl,
    apiVersion,
    accessToken,
    soql: `SELECT Id, Status, CampaignId, ContactId, LeadId FROM CampaignMember WHERE Id = '${membershipIdIn}' LIMIT 1`,
    httpStatuses,
    name: 'sfdc_query_verify',
    timeoutMs: 4000,
  });
  if (verified.err || !verified.record) {
    return finish({
      actionName: THIS_ACTION,
      level: 'ERROR',
      errorState: 1,
      httpStatuses,
      httpMessage: deriveHttpMessage(httpStatuses, { sfdc_query_verify: verified.err || 'CampaignMember not found' }),
      errorMessage: 'Unable to verify existing CampaignMember',
    });
  }

  if (campaignId && safeStr(verified.record.CampaignId) && safeStr(verified.record.CampaignId) !== campaignId) {
    httpStatuses.input_salesforce_campaign_id = 'INVALID';
    return finish({
      actionName: THIS_ACTION,
      level: 'ERROR',
      errorState: 1,
      httpStatuses,
      httpMessage: deriveHttpMessage(httpStatuses, {
        input_salesforce_campaign_id: 'Existing CampaignMember does not match CampaignId',
      }),
      errorMessage: 'CampaignMember/Campaign mismatch',
    });
  }

  if (!outputs.salesforcecontactid && verified.record.ContactId) outputs.salesforcecontactid = safeStr(verified.record.ContactId);
  if (!outputs.salesforceleadid && verified.record.LeadId) outputs.salesforceleadid = safeStr(verified.record.LeadId);

  outputs.membership_status = safeStr(verified.record.Status);
  otherPayload.current_status = outputs.membership_status;
  if (norm(outputs.membership_status) === norm(desiredStatus)) {
    outputs.operation = 'skipped';
    otherPayload.operation = 'skipped';
    return finish({ actionName: THIS_ACTION, level: 'INFO', errorState: 0, httpStatuses });
  }

  const patchResp = await callOnce('sfdc_patch_campaign_member', 'PATCH', `${sfdcBase(instanceUrl, apiVersion)}/sobjects/CampaignMember/${membershipIdIn}`, {
    http: httpStatuses,
    headers: sfdcHeaders(accessToken),
    jsonBody: { Status: desiredStatus },
    timeoutMs: 5000,
  });
  if (patchResp.err || !patchResp.resp || patchResp.resp.status !== 204) {
    const override =
      patchResp.err ||
      sfdcErrorSummary(patchResp.resp ? patchResp.resp.status : 0, patchResp.resp ? patchResp.resp.json : null, patchResp.resp ? patchResp.resp.text : '');
    if (isLockError(override)) {
      outputs.lock_error = 'true';
      outputs.operation = 'lock_error';
      otherPayload.lock_error = true;
      otherPayload.operation = 'lock_error';
      return finish({
        actionName: THIS_ACTION,
        level: 'WARN',
        errorState: 1,
        httpStatuses,
        httpMessage: deriveHttpMessage(httpStatuses, { sfdc_patch_campaign_member: override }),
        errorMessage: 'Salesforce PATCH retry failed with lock error',
      });
    }
    return finish({
      actionName: THIS_ACTION,
      level: 'ERROR',
      errorState: 1,
      httpStatuses,
      httpMessage: deriveHttpMessage(httpStatuses, { sfdc_patch_campaign_member: override }),
      errorMessage: 'Salesforce PATCH retry failed',
    });
  }

  const postPatch = await sfdcQueryOne({
    instanceUrl,
    apiVersion,
    accessToken,
    soql: `SELECT Id, Status FROM CampaignMember WHERE Id = '${membershipIdIn}' LIMIT 1`,
    httpStatuses,
    name: 'sfdc_query_verify_after_patch',
    timeoutMs: 4000,
  });
  if (postPatch.err || !postPatch.record) {
    return finish({
      actionName: THIS_ACTION,
      level: 'ERROR',
      errorState: 1,
      httpStatuses,
      httpMessage: deriveHttpMessage(httpStatuses, {
        sfdc_query_verify_after_patch: postPatch.err || 'No CampaignMember record',
      }),
      errorMessage: 'Unable to verify CampaignMember after PATCH retry',
    });
  }

  outputs.membership_status = safeStr(postPatch.record.Status);
  outputs.operation = 'patched';
  otherPayload.operation = 'patched';
  otherPayload.verified_status = outputs.membership_status;
  if (norm(outputs.membership_status) !== norm(desiredStatus)) {
    httpStatuses.sfdc_verify_status = 'INVALID';
    return finish({
      actionName: THIS_ACTION,
      level: 'ERROR',
      errorState: 1,
      httpStatuses,
      httpMessage: deriveHttpMessage(httpStatuses, {
        sfdc_verify_status: `Status mismatch (wanted='${desiredStatus}', got='${outputs.membership_status}')`,
      }),
      errorMessage: 'CampaignMember status did not persist (likely invalid status for campaign)',
    });
  }

  return finish({ actionName: THIS_ACTION, level: 'INFO', errorState: 0, httpStatuses });
}

exports.main = async (event, callback) => {
  try {
    callback(await core(event || {}));
  } catch (err) {
    const outputs = blankOutputs();
    const httpStatuses = { uncaught_exception: 'Request_error' };
    callback(
      finalize(outputs, {
        actionName: THIS_ACTION,
        level: 'ERROR',
        errorState: 1,
        httpStatuses,
        httpMessage: deriveHttpMessage(httpStatuses, { uncaught_exception: safeStr(err && err.message ? err.message : err) }),
        otherPayload: { operation: 'failed', action_variant: ACTION_VARIANT },
        errorMessage: 'Unhandled exception in new_delegate_record_CCA4',
      })
    );
  }
};

exports._internal = {
  core,
  getPrivateKeyFromSecrets,
  getSalesforceAccessToken,
  blankOutputs,
  finalize,
};

/*
 * Masks delegate workflow fields and ships a Grafana Loki log line for the preceding action result.
 * Branch before: Run after the preceding workflow action emits loggable fields for this delegate record path.
 * Branch after: Branch only on logger result: dry run, logged successfully, or logging error.
 * Expected inputs: upstream workflow fields via event.inputFields limited to log, http, http_message, and other.
 * Expected outputs: logged, simulated, payload (dry run only), logging_http_status, error.
 */
const https = require('https');
const { URL } = require('url');

const DEFAULT_ACTION = 'new_delegate_record_CCA4';
const WORKFLOW_NAME = 'Delegate New > New SFDC Campaign member';
const GRAFANA_ENV = 'prod';
const JOB_NAME = 'swoogo_sfdc_campaign';
const LOKI_ENDPOINT = (process.env.LOKI_URL || process.env.grafana_url || 'https://logs-prod-012.grafana.net/loki/api/v1/push').trim();
const EMAIL_RE = /([A-Za-z0-9._%+-]+)@([A-Za-z0-9.-]+\.[A-Za-z]{2,})/g;

function safeJsonParse(value, fallback) {
  if (!value) return fallback;
  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      return parsed && typeof parsed === 'object' ? parsed : fallback;
    } catch (_err) {
      return fallback;
    }
  }
  return typeof value === 'object' ? value : fallback;
}

function maskLocal(local) {
  const value = String(local || '');
  const first = value.charAt(0) || 'a';
  const last = value.charAt(value.length - 1) || first;
  return `${first}***${last}`;
}

function maskEmailString(value) {
  return String(value || '').replace(EMAIL_RE, (_match, local, domain) => `${maskLocal(local)}@${domain}`);
}

function maskDeep(value) {
  if (Array.isArray(value)) return value.map((item) => maskDeep(item));
  if (value && typeof value === 'object') {
    return Object.keys(value).reduce((acc, key) => {
      acc[key] = maskDeep(value[key]);
      return acc;
    }, {});
  }
  if (typeof value === 'string') return maskEmailString(value);
  return value;
}

function buildLogLine(inputs) {
  const parsedLog = safeJsonParse(inputs.log, {});
  const payload = {
    workflow_action: parsedLog.workflow_action || inputs.workflow_action || DEFAULT_ACTION,
    workflow_name: parsedLog.workflow_name || inputs.workflow_name || WORKFLOW_NAME,
    level: parsedLog.level || inputs.level || 'INFO',
    error_state: parsedLog.error_state || inputs.error_state || '0',
    hs_delegate_id: parsedLog.hs_delegate_id || inputs.hs_delegate_id || '',
    salesforce_campaign_id: parsedLog.salesforce_campaign_id || inputs.salesforce_campaign_id || '',
    salesforce_campaign_membership_id:
      parsedLog.salesforce_campaign_membership_id || inputs.salesforce_campaign_membership_id || '',
    membership_id: parsedLog.membership_id || inputs.membership_id || '',
    membership_status: parsedLog.membership_status || inputs.membership_status || '',
    salesforce_campaign_member_status:
      parsedLog.salesforce_campaign_member_status || inputs.salesforce_campaign_member_status || '',
    salesforcecontactid: parsedLog.salesforcecontactid || inputs.salesforcecontactid || '',
    salesforceleadid: parsedLog.salesforceleadid || inputs.salesforceleadid || '',
    email: parsedLog.email || inputs.email || '',
    error: {
      http: (parsedLog.error && parsedLog.error.http) || safeJsonParse(inputs.http, {}),
      http_message: (parsedLog.error && parsedLog.error.http_message) || safeJsonParse(inputs.http_message, {}),
    },
    other: safeJsonParse(inputs.other, parsedLog.other || {}),
  };
  payload.campaign_member_id = payload.membership_id || payload.salesforce_campaign_membership_id || '';
  if (parsedLog.operation || payload.other.operation) payload.operation = parsedLog.operation || payload.other.operation;
  if (parsedLog.action_variant || payload.other.action_variant) payload.action_variant = parsedLog.action_variant || payload.other.action_variant;
  if (payload.other.lock_error !== undefined) payload.lock_error = payload.other.lock_error;
  return JSON.stringify(maskDeep(payload));
}

async function postJson(url, payload, user, token) {
  const target = new URL(url);
  const body = JSON.stringify(payload);
  const auth = `Basic ${Buffer.from(`${user}:${token}`).toString('base64')}`;

  if (typeof fetch === 'function') {
    const resp = await fetch(target.toString(), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: auth },
      body,
    });
    const text = await resp.text();
    if (resp.status < 200 || resp.status >= 300) throw new Error(text || `HTTP ${resp.status}`);
    return { status: resp.status };
  }

  return new Promise((resolve, reject) => {
    const req = https.request(
      target,
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(body),
          Authorization: auth,
        },
      },
      (res) => {
        const chunks = [];
        res.on('data', (chunk) => chunks.push(chunk));
        res.on('end', () => {
          const text = Buffer.concat(chunks).toString('utf8');
          if ((res.statusCode || 0) < 200 || (res.statusCode || 0) >= 300) {
            reject(new Error(text || `HTTP ${res.statusCode || 0}`));
            return;
          }
          resolve({ status: res.statusCode || 0 });
        });
      }
    );
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

exports.main = async (event, callback) => {
  try {
    const user = (process.env.grafana_user || process.env.GRAFANA_USER || '').trim();
    const token = (process.env.grafana_token || process.env.GRAFANA_TOKEN || '').trim();
    if (!user || !token) throw new Error('Missing grafana_user or grafana_token environment variables.');

    const payload = {
      streams: [
        {
          stream: {
            service_name: 'hubspot',
            environment: GRAFANA_ENV,
            process: 'workflow',
            team: 'marketing_technology',
            job: JOB_NAME,
          },
          values: [[`${Date.now()}000000`, buildLogLine((event && event.inputFields) || {})]],
        },
      ],
    };

    if (String(process.env.GRAFANA_DRY_RUN || '').trim() === '1') {
      callback({ outputFields: { logged: false, simulated: true, payload } });
      return;
    }

    const res = await postJson(LOKI_ENDPOINT, payload, user, token);
    callback({ outputFields: { logged: true, simulated: false, logging_http_status: res.status } });
  } catch (error) {
    callback({
      outputFields: {
        logged: false,
        error: String(error && error.message ? error.message : error),
      },
    });
  }
};
